// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Veriyi yorumlama, nedensellik-korelasyon, yanlılık ve geçerlilik (orta).
const ozResearch4Orta = <(String, String, List<String>, String)>[
  ('Bir araştırmacı iki ilişki buluyor: A için r = -0,82, B için r = +0,45. Hangi yorum doğrudur?', 'A ilişkisi B\'den daha güçlüdür, yalnızca yönü terstir.', ['B ilişkisi daha güçlüdür, çünkü pozitif katsayı negatif olandan her zaman büyüktür.', 'A ilişkisi zayıftır çünkü değeri sıfırdan küçüktür.', 'İki ilişki eşit güçtedir çünkü işaretleri farklıdır.'], 'İlişkinin gücü katsayının mutlak değerine bakılarak değerlendirilir. |-0,82| değeri 0,45\'ten büyüktür; eksi işaret yalnızca yönü belirtir.'),
  ('Determinasyon katsayısı r² neyi ifade eder?', 'Bir değişkendeki varyansın diğeriyle açıklanan payını', ['İki değişkenin ortalamaları arasındaki farkı', 'Örneklemdeki aykırı değerlerin yüzdesini', 'Bir değişkenin diğerine neden olma olasılığını yüzde olarak'], 'r² doğrusal modelde bir değişkenin varyansının ne kadarının diğeriyle birlikte açıklandığını gösterir. Nedensellik olasılığı değildir.'),
  ('İki değişken arasında r = 0,60 bulunmuştur. Bir değişkendeki varyansın yaklaşık yüzde kaçı diğeriyle ortak açıklanır?', '%36', ['%60', '%6', '%77'], 'r² = 0,60 × 0,60 = 0,36\'dır, yani varyansın yaklaşık %36\'sı ortak açıklanır. Yalnız r\'ye bakmak ilişkiyi olduğundan güçlü gösterebilir.'),
  ('Bir gazete "Daha çok kitabı olan evlerde büyüyen çocukların okul başarısı daha yüksek; her eve kitap dağıtılırsa başarı artar" diye yazıyor. Bu çıkarımın temel zayıflığı nedir?', 'Kitap sayısı ailenin eğitim ve gelir düzeyini yansıtıyor olabilir.', ['Kitap sayısı ölçülemeyen bir değişkendir.', 'Okul başarısı notlarla ölçüldüğü için hiçbir zaman sayısal olarak karşılaştırılamaz.', 'Korelasyon yalnızca yetişkinler için hesaplanır.'], 'Evdeki kitap sayısı ebeveyn eğitimi, gelir ve okuma alışkanlığıyla ilişkilidir. Bu etkenler başarıyı da etkiler; kitap dağıtmak onları değiştirmeyebilir.'),
  ('Gözlemsel bir çalışmada, kahve içenlerde akciğer kanseri daha sık görülmüş; ancak kahve içenlerin sigara içme oranının da daha yüksek olduğu anlaşılmıştır. Burada sigara hangi rolü oynar?', 'Karıştırıcı değişken', ['Bağımlı değişken', 'Aracı değişken', 'Kontrol grubu'], 'Sigara hem kahve tüketimiyle hem de kanserle ilişkilidir ve kahve ile kanser arasında sahte bir ilişki yaratabilir. Bu, karıştırıcı değişkenin tanımıdır.'),
  ('Gözlemsel bir çalışmada yaşın karıştırıcı etkisini azaltmak için analiz aşamasında hangi yol izlenebilir?', 'Sonuçları yaş gruplarına ayırarak ayrı ayrı incelemek', ['Yaşı soru formundan çıkarmak', 'Yalnızca ortalama yaşı rapor etmek', 'Örneklemi büyütüp yaşın etkisini tamamen göz ardı etmek'], 'Tabakalama (yaş gruplarına göre ayrı analiz) ya da regresyonla düzeltme, bilinen bir karıştırıcının etkisini azaltır. Örneklemi büyütmek karıştırıcılığı ortadan kaldırmaz.'),
  ('İstatistiksel düzeltme yapılmış gözlemsel çalışmalarda bile nedensel sonuçlara temkinli yaklaşılmasının başlıca nedeni nedir?', 'Ölçülmemiş karıştırıcılar düzeltilemez.', ['Düzeltme işlemi her zaman sonucu tersine çevirir.', 'Regresyon yalnızca deney verisinde kullanılabilir.', 'Düzeltme örneklem büyüklüğünü yarıya indirir.'], 'Analiz yalnızca ölçülmüş değişkenleri hesaba katabilir. Ölçülmemiş karıştırıcıların etkisi kalan karıştırıcılık olarak sonuçlarda kalır.'),
  ('Hastanede yatan hastalarda ilaç kullanımı ile ölüm oranı arasında pozitif bir ilişki bulunmuştur. Bu ilişkinin ilaçların öldürücü olduğunu göstermemesinin en olası nedeni nedir?', 'Ağır hastaların daha fazla ilaç alması', ['İlaçların hiçbir etkisinin olmaması', 'Ölüm oranının yanlış hesaplanması', 'İlaçların yalnızca sağlıklılara verilmesi'], 'Hastalığın ağırlığı hem ilaç sayısını hem de ölüm riskini artırır. Bu durum "endikasyon karıştırıcılığı" olarak bilinir ve nedensel yorumu engeller.'),
  ('Ters nedensellik olasılığını azaltmak için kesitsel bir çalışma yerine hangi yaklaşım daha uygundur?', 'Neden olduğu düşünülen değişkenin sonuçtan önce ölçüldüğü izlem çalışması', ['Daha çok katılımcıyla aynı anda yapılan tek ölçüm', 'Yalnızca uç değerli katılımcıların seçilmesi', 'Değişkenlerin yerini değiştirerek korelasyonun yeniden hesaplanması'], 'Zamansal öncelik nedenselliğin koşullarından biridir. İzlem çalışmalarında maruziyet sonuçtan önce ölçüldüğünden yön daha iyi kestirilir.'),
  ('Bir çalışmada, düşük kilolu yaşlıların ölüm oranının daha yüksek olduğu ve bu yüzden zayıflığın zararlı olduğu ileri sürülüyor. Ters nedensellik açısından hangi itiraz yapılabilir?', 'Ağır bir hastalık hem kilo kaybına hem ölüme yol açmış olabilir.', ['Kilo, ölümle hiçbir biçimde ilişkili olamaz.', 'Yaşlılarda kilo ölçümü yapılamaz.', 'Zayıflık her yaş grubunda ölüm riskine karşı güçlü bir koruyucu etkendir.'], 'Henüz tanı konmamış hastalıklar kilo kaybına yol açar ve ölüm riskini artırır. Bu durumda düşük kilo nedenden çok sonuçtur; çalışmalar bu yüzden ilk yılları dışarıda bırakabilir.'),
  ('Binlerce rastgele değişken çiftinin korelasyonu tarandığında bazı güçlü ilişkiler bulunması neden şaşırtıcı değildir?', 'Çok sayıda karşılaştırmada bazıları şansla güçlü çıkar.', ['Rastgele değişkenler her zaman ilişkilidir.', 'Korelasyon katsayısı büyük veri setlerinde güvenilir biçimde hesaplanamaz.', 'Bilgisayarlar korelasyonu abartarak hesaplar.'], 'Ne kadar çok çift incelenirse şansla güçlü görünen ilişki sayısı o kadar artar. Bu yüzden önceden kurulmuş bir hipotez ve bağımsız doğrulama gerekir.'),
  ('Zamanla artan iki değişken (örneğin bir ülkede internet kullanımı ve ortalama yaşam süresi) arasında yüksek korelasyon bulunmasının nedensellik açısından yanıltıcı olabilmesinin başlıca sebebi nedir?', 'Her iki seri de ortak bir zaman eğilimi taşır.', ['Zaman serilerinde korelasyon hesaplanamaz.', 'Yaşam süresi her yıl azalır.', 'İnternet kullanımı ölçülemez.'], 'İki seri zamanla birlikte yükseldiğinde, aralarında bağ olmasa bile yüksek korelasyon görülür. Eğilim çıkarılınca bu ilişki çoğu kez kaybolur.'),
  ('Epidemiyolog Austin Bradford Hill\'in 1965\'te önerdiği nedensellik ölçütleri arasında hangisi, mantıksal olarak zorunlu kabul edilen tek ölçüttür?', 'Zamansallık', ['Benzetme', 'Özgüllük', 'Biyolojik akla yatkınlık'], 'Bir etkenin sonuca yol açabilmesi için ondan önce ortaya çıkması gerekir. Diğer ölçütler kanıtı güçlendirir ama tek tek zorunlu değildir.'),
  ('Bradford Hill ölçütleriyle ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Kanıtı tartmaya yardımcı bakış açılarıdır, kesin liste değildir.', ['Dokuz ölçütün tamamı karşılanmadan nedensellik kabul edilemez.', 'Yalnızca laboratuvar deneylerinde kullanılabilirler.', 'Her ölçüt tek başına nedenselliği kanıtlar.'], 'Hill bu ölçütleri katı kurallar olarak değil, yargıya destek olan bakış açıları olarak sunmuştur. Zamansallık dışındakilerin hiçbiri tek başına zorunlu değildir.'),
  ('Bir etkenin hastalığa yol açtığı iddiasının bilinen biyoloji ve kimya bilgisiyle bağdaşması, hangi nedensellik ölçütü kapsamında değerlendirilir?', 'Akla yatkınlık', ['Uyumluluk', 'Doz-yanıt', 'Güç'], 'Makul bir biyolojik mekanizmanın bulunması nedensel iddiayı destekler. Ancak bilgi sınırlı olduğunda mekanizmanın henüz bilinmemesi nedenselliği dışlamaz.'),
  ('Sigarayı bırakan kişilerde akciğer kanseri riskinin zamanla azalması, nedensel ilişki için hangi türden destek sağlar?', 'Deney (maruziyetin kaldırılması) ölçütüne dayanan kanıt', ['Özgüllüğe, yani tek nedenin tek sonuç vermesine dayanan kanıt', 'Benzetmeye dayanan kanıt', 'Tesadüfe dayanan kanıt'], 'Maruziyetin ortadan kalkmasıyla riskin düşmesi, Hill\'in "deney" ölçütüyle uyumludur ve nedenselliği güçlendirir.'),
  ('1854 Londra kolera salgınında John Snow\'un çalışmasını güçlü kılan özellik neydi?', 'Farklı şirketlerden su alan benzer evleri karşılaştırması', ['Hastalara rastgele kirli su içirmesi', 'Koleranın bakteriyel etkenini mikroskopla ilk kez göstermesi ve adlandırması', 'Yalnızca hastane kayıtlarındaki tanılara dayanması'], 'Snow, aynı mahallelerde farklı şirketlerden su alan haneleri karşılaştırdı. Bu düzen, karıştırıcıları büyük ölçüde dengeleyen bir doğal deney işlevi gördü.'),
  ('Gözlemsel çalışmalar hangi durumda rastgele deneyden daha değerli bilgi sağlayabilir?', 'Nadir ve uzun vadeli yan etkileri izlemede', ['Kısa süreli bir ilacın etkinliğini kontrollü koşullarda ölçmede', 'Plasebo etkisini ayırt etmede', 'Grupları başlangıçta eşitlemede'], 'Deneyler genellikle sınırlı sayıda kişiyle kısa süre yürütülür. Binlerce kişiyi yıllarca izleyen gözlemsel kayıtlar nadir yan etkileri yakalamada üstündür.'),
  ('Bir üniversitede kadın adayların genel kabul oranı erkeklerden düşük görünürken, bölümler tek tek incelendiğinde hemen her bölümde kadınların kabul oranı erkeklerinkine eşit ya da daha yüksek çıkıyor. Bu duruma ne ad verilir?', 'Simpson paradoksu', ['Ekolojik yanılgı', 'Ortalamaya dönüş olgusu', 'Hawthorne etkisi'], 'Gruplar birleştirildiğinde ilişkinin yönünün değişmesi Simpson paradoksudur. 1973 Berkeley verisinde kadınların kabul oranı düşük bölümlere daha çok başvurması bu tabloyu yaratmıştı.'),
  ('Simpson paradoksunun ortaya çıkmasında temel rolü genellikle ne oynar?', 'Gruplara dengesiz dağılmış gizli bir değişken', ['Ölçüm aletlerinin bozuk ya da yanlış ayarlanmış olması', 'Örneklemin çok büyük olması', 'Verilerin yüzdeye çevrilmesi'], 'Gruplama değişkeni hem maruziyetle hem sonuçla ilişkiliyse ve gruplara dengesiz dağılmışsa, birleştirilmiş veri alt gruplardakinin tersi bir eğilim gösterebilir.'),
  ('Bir şirkette her departmanda maaş artışı kadın çalışanlar lehine olmasına rağmen, şirket genelinde ortalama artış erkeklerde daha yüksek çıkmıştır. Bu durumu anlamak için ilk incelenmesi gereken nedir?', 'Kadın ve erkek çalışanların departmanlara dağılımı', ['Şirketin kuruluş yılı', 'Maaşların hangi para birimiyle ödendiği', 'Çalışanların toplam sayısının tek mi çift mi olduğu'], 'Departmanlar arası artış oranları farklıysa ve cinsiyetler bu departmanlara farklı dağılmışsa genel ortalama alt grupların tersini gösterebilir.'),
  ('Hangi araştırma sorusu ekolojik yanılgı riskini en az taşır?', 'Sigara vergisi artırılan ülkelerde toplam sigara satışları azaldı mı?', ['Ülke ortalaması yüksek olduğu için bu ülkedeki her öğrenci başarılı mı?', 'Yağlı beslenen ülkelerde kalp hastası olanlar yağlı mı besleniyor?', 'Zengin ilçelerde oy veren herkes aynı partiyi mi seçiyor?'], 'Bu soru grup düzeyinde bir sonucu (ülke satışları) grup düzeyindeki bir müdahaleyle ilişkilendirir ve bireyler hakkında iddiada bulunmaz.'),
  ('Ortalamaya dönüş en belirgin olarak hangi koşulda ortaya çıkar?', 'Ölçüm kısmen şansa bağlıyken uç değerliler seçildiğinde', ['Ölçümler hatasız ve kusursuz güvenilir olduğunda', 'Tüm katılımcılar rastgele seçildiğinde ve kimse uç değer taşımadığında', 'Yalnızca tek bir ölçüm yapıldığında'], 'İki ölçüm arasındaki korelasyon 1\'den küçükse, ilk ölçümde uç olanlar ikinci ölçümde ortalamaya daha yakın çıkma eğilimindedir.'),
  ('İki ölçüm arasındaki korelasyon sıfıra yakın olduğunda ortalamaya dönüş için ne söylenebilir?', 'Dönüş çok güçlüdür; uçlar ikinci ölçümde neredeyse ortalamaya iner.', ['Ortalamaya dönüş hiç gözlenmez.', 'Uç değerler ikinci ölçümde daha da uçlaşarak evren ortalamasından uzaklaşır.', 'Dönüş yalnızca pozitif değerlerde görülür.'], 'Korelasyon ne kadar düşükse ikinci ölçüm ilk ölçümden o kadar bağımsızdır. Bu nedenle uçlar ikinci kez ölçüldüğünde ortalamaya en güçlü biçimde yaklaşır.'),
  ('Bir araştırmacı, yeni bir uyku ilacını yalnızca son bir haftada en kötü uykuyu çeken hastalara verip bir hafta sonra iyileşme görüyor. Bu tasarımın ortalamaya dönüşe karşı en etkili düzeltmesi nedir?', 'Aynı ölçütle seçilmiş hastalardan rastgele bir kontrol grubu oluşturmak', ['Hasta sayısını iki katına çıkarmak', 'İlacın dozunu artırmak', 'Uyku süresini dakika yerine saat cinsinden ölçüp ölçme hatasını azaltmak'], 'Kontrol grubu da aynı ölçütle seçildiği için o da ortalamaya döner. İki grup arasındaki fark ilacın gerçek etkisini gösterir.'),
  ('Fabrika çalışanlarının ölüm oranlarının genel nüfustan düşük çıkması neden işyerinin sağlıklı olduğunu kanıtlamaz?', 'İşe ancak çalışabilecek kadar sağlıklı olanlar alınır.', ['Fabrika çalışanlarının yaşı hiç kaydedilmez.', 'Ölüm oranları yalnızca genel nüfus için hesaplanabilen bir göstergedir.', 'Fabrikalarda hiç kimse hastalanmaz.'], 'Bu "sağlıklı işçi etkisi" olarak bilinen bir seçim yanlılığıdır. Karşılaştırma için genel nüfus yerine başka bir çalışan grubu kullanılmalıdır.'),
  ('Bir müzik okulu mezunlarının %80\'inin profesyonel müzisyen olduğunu duyuruyor; ancak okul, ilk yılın sonunda başarısız öğrencileri okuldan uzaklaştırıyor. Bu istatistiği yorumlarken asıl sorun nedir?', 'Mezunlar zaten en başarılılardan oluştuğu için katkı abartılır.', ['Profesyonel müzisyenliğin tanımı ülkeden ülkeye ve yıldan yıla hiç değişmez.', 'Mezun sayısının çok yüksek olması', 'Okulun ilk yılda sınav yapmaması'], 'Okul, sonucu etkileyen bir süzgeç uygulamıştır. Başlangıçta kayıt olanların tümüne bakılmadan okulun başarısı doğru değerlendirilemez.'),
  ('Seçim yanlılığının neden örneklemi büyüterek giderilemeyeceğini en iyi hangi ifade açıklar?', 'Sistematik hata örneklem büyüdükçe kaybolmaz, yalnızca tekrarlanır.', ['Büyük örneklemlerde istatistiksel test yapılamaz.', 'Örneklem büyüdükçe seçim yanlılığı kendiliğinden tersine döner ve sıfırlanır.', 'Büyük örneklemler her zaman temsil edicidir.'], 'Büyük örneklem rastlantısal hatayı azaltır ama seçim sürecindeki sistematik kaymayı düzeltmez. 1936 Literary Digest anketi milyonlarca yanıta rağmen yanılmıştı.'),
  ('II. Dünya Savaşı\'nda istatistikçi Abraham Wald, görevden dönen uçaklarda kurşun deliklerinin en az bulunduğu bölgelerin zırhlanmasını önermiştir. Bu önerinin mantığı neydi?', 'O bölgelerden vurulan uçaklar geri dönememişti.', ['O bölgeler uçağın en hafif kısımlarıydı.', 'Düşman uçaksavarları bu bölgelere hiçbir zaman nişan alamıyordu.', 'Delikli bölgeler zaten fazla zırhlıydı.'], 'Yalnızca geri dönebilen uçaklar incelendiği için ölümcül isabetler veride görünmüyordu. Bu, hayatta kalan yanlılığının en bilinen örneğidir.'),
  ('Bir yatırım dergisi, "Son 10 yılda faaliyet gösteren fonların ortalama getirisi %12" diye yazıyor; ancak bu dönemde kapanan fonlar hesaba katılmamış. Bu durum ortalamayı nasıl etkiler?', 'Kapanan kötü fonlar çıkarıldığı için ortalama şişer.', ['Ortalama olduğundan düşük görünür.', 'Kapanan fonlar çok az olduğu için ortalama hiç değişmez ve yanlılık oluşmaz.', 'Ortalama hesaplanamaz hâle gelir.'], 'Kapanan fonlar genellikle başarısız olanlardır. Onları dışarıda bırakmak yalnızca hayatta kalanların başarısını gösterir ve getiriyi şişirir.'),
  ('Psikolog Peter Wason\'ın 2-4-6 görevinde katılımcılar kuralı bulmak için çoğunlukla 8-10-12 gibi kendi tahminlerine uyan diziler denemiştir. Bu davranış neyi gösterir?', 'Hipotezlerin çürütülmek yerine doğrulanmaya çalışıldığını', ['Sayı dizilerinin insanlar tarafından hiç anlaşılamadığını', 'Katılımcıların kuralı her zaman ilk denemede bulduğunu', 'Rastgele denemenin en verimli yol olduğunu'], 'Gerçek kural "artan herhangi üç sayı"ydı. Katılımcılar varsayımlarını çürütebilecek dizileri pek denemedi; bu, doğrulama yanlılığını gösteren klasik bir deneydir.'),
  ('Bir araştırmacı verisini analiz ederken beklediği sonucu veren yöntemi kullanmaya devam ediyor, beklenmedik sonuç verenlerde ise "hata olmalı" diyerek yeniden kontrol yapıyor. Bu davranışın sonucu ne olur?', 'Bulgular beklentiye doğru kayar.', ['Analiz tamamen yansız hâle gelir, çünkü her sonuç bir kez kontrol edilir.', 'Sonuçların güvenirliği iki katına çıkar.', 'Beklenmedik bulgular daha sık yayımlanır.'], 'Yalnız beklenmedik sonuçların ayrıntılı denetlenmesi asimetrik bir hata ayıklama yaratır. Beklenen sonuçlardaki hatalar fark edilmeden kalır.'),
  ('Bir kişi, burcunun özelliklerini okuduktan sonra kendisine uyan cümleleri hatırlayıp uymayanları unutuyor ve "burçlar doğru çıkıyor" diyor. Bu durum hangi iki eğilimin birleşimine örnektir?', 'Seçici hatırlama ve doğrulama yanlılığı', ['Ortalamaya dönüş ve Simpson paradoksu', 'Hawthorne etkisi ile plasebo etkisinin birlikte görülmesi', 'Yayın yanlılığı ve kayıp yanlılığı'], 'Kişi uyan bilgileri öne çıkarıp uymayanları unutarak inancını destekler. Ayrıca bu tür genel ifadeler herkese uyacak biçimde yazılır (Barnum etkisi).'),
  ('Klinik çalışmaların başlamadan önce kamuya açık bir kayıt sistemine kaydedilmesi zorunluluğu hangi sorunu azaltmayı hedefler?', 'Olumsuz sonuçlu çalışmaların gizlenmesini', ['Katılımcıların gruplara rastgele atanmasını', 'Hastaların ilacı düzenli almamasını', 'Çalışmaların çok uzun sürmesini'], 'Önceden kayıtlı çalışmaların sonucu yayımlanmasa bile varlığı bilinir. Bu, yayın yanlılığını ve sonuç ölçütünün sonradan değiştirilmesini görünür kılar.'),
  ('Bir çalışmanın önceden belirlenen ana sonuç ölçütü anlamlı çıkmayınca, araştırmacıların anlamlı çıkan bir yan ölçütü öne çıkarıp raporlaması hangi sorunun bir türüdür?', 'Seçici sonuç raporlama', ['Hatırlama yanlılığı', 'Ekolojik yanılgı', 'Tavan etkisi'], 'Hangi sonuçların raporlanacağının bulgulara göre seçilmesi, çalışma içi yayın yanlılığıdır. Ön kayıtlarla karşılaştırma bu durumu ortaya çıkarabilir.'),
  ('Bir vaka-kontrol çalışmasında, bebeği doğum kusuruyla dünyaya gelen anneler, sağlıklı bebek doğuran annelere göre gebelikte aldıkları ilaçları daha ayrıntılı hatırlıyor. Bu durum hangi yanlılığı doğurur?', 'Hatırlama yanlılığı', ['Hayatta kalan yanlılığı', 'Yayın yanlılığı', 'Hawthorne etkisi'], 'Olumsuz bir sonuç yaşayan kişiler olası nedenleri daha çok düşünür ve hatırlar. Bu, gruplar arasında maruziyet bildiriminin farklı olmasına ve sahte ilişkilere yol açar.'),
  ('Bir beslenme anketinde katılımcılardan son bir yılda ne kadar sebze yediklerini hatırlamaları isteniyor. Yanıtların çoğu, son haftalardaki beslenmeyi yansıtıyor. Bu durum hangi tür hatayı gösterir?', 'Yakın geçmişin belleğe baskın gelmesi', ['Rastgele atamanın yapılmamasından doğan seçim hatası', 'Huni grafiğindeki asimetriden doğan yayın yanlılığı hatası', 'Yüksek korelasyondan doğan ekolojik hata'], 'İnsanlar uzun dönemleri değerlendirirken en yeni ve en canlı anılara fazla ağırlık verir. Bu da uzun süreli maruziyetlerin yanlış ölçülmesine yol açar.'),
  ('Psikolog Robert Rosenthal\'ın 1960\'larda yaptığı deneylerde, öğretmenlere bazı öğrencilerin "gelişmeye hazır" olduğu rastgele söylenmiş ve bu öğrencilerin başarısı daha çok artmıştır. Bu olgu hangi adla bilinir?', 'Pygmalion etkisi', ['Hawthorne etkisi', 'Plasebo etkisi', 'Dunning-Kruger etkisi'], 'Rosenthal ve Jacobson\'ın çalışması, öğretmen beklentilerinin öğrenci başarısını etkileyebildiğini gösterdi; bu, beklentinin kendini gerçekleştirmesidir.'),
  ('20. yüzyıl başında "Akıllı Hans" adlı atın aritmetik soruları toynağıyla vurarak yanıtladığı sanılmıştı. Psikolog Oskar Pfungst\'un ortaya çıkardığı açıklama neydi?', 'Soranların farkında olmadan verdiği beden işaretlerini izlemesi', ['Atın gerçekten toplama ve çıkarma yapabilmesi', 'Sahibinin atı gizlice ve belirli aralıklarla elektrikle uyarması', 'Soruların her zaman aynı yanıtı gerektirmesi'], 'Doğru sayıya gelindiğinde soranların bilinçsizce gerildiği ya da rahatladığı görüldü. Soran kişi yanıtı bilmediğinde at başarısız oldu; bu, deneyci beklentisinin klasik örneğidir.'),
  ('Bir araştırmacı, sınıfta çocukların "saldırgan davranış" sayısını kaydederken yeni programa katılan çocuklardaki belirsiz itişmeleri oyun, kontrol grubundakileri ise saldırganlık olarak not ediyor. Bu tutum ölçümü nasıl etkiler?', 'Gruplar arasında sistematik bir ölçüm farkı yaratır.', ['Yalnızca rastlantısal hatayı artırır, ortalamaları değiştirmez.', 'Ölçümün güvenirliğini artırır, çünkü tek kişi kodlama yapar.', 'Yalnızca kontrol grubunun örneklem büyüklüğünü değiştirir.'], 'Belirsiz davranışların gruba göre farklı kodlanması ölçümü beklenen yöne kaydırır. Kodlayıcının grupları bilmemesi ve açık tanımlar bu yanlılığı azaltır.'),
  ('Bir akupunktur çalışmasında kontrol grubuna iğneler deriyi delmeyen sahte noktalara uygulanıyor. Bu düzenin amacı nedir?', 'Ritüelin etkisini gerçek iğnelemeden ayırmak', ['Kontrol grubunun hiçbir biçimde tedavi almamasını garanti etmek', 'Deney grubunun daha çok ağrı hissetmesini sağlamak', 'Örneklem büyüklüğünü artırmak'], 'Sahte (şam) uygulama, katılımcının tedavi gördüğü inancını korur. Böylece iki grup arasındaki fark, iğnelemenin özgül etkisine bağlanabilir.'),
  ('Ağrı kesici denemelerinde pahalı görünen plasebo haplarının ucuz görünenlerden daha çok rahatlama sağladığı bildirilmiştir. Bu bulgu en çok neyi gösterir?', 'Beklentinin algılanan etkiyi değiştirebildiğini', ['Pahalı hapların ucuzlara göre daha çok etken madde içerdiğini', 'Hap renginin kimyasal etkisi olduğunu', 'Plasebonun her zaman zararlı olduğunu'], 'Etken madde aynı (yok) olduğu hâlde fiyat ve görünüm beklentiyi değiştirir. Bu nedenle karşılaştırılan haplar görünüşte eşdeğer hazırlanmalıdır.'),
  ('Kendini bildirim yoluyla ölçülen "haftalık egzersiz süresi" ile giyilebilir cihazlarla ölçülen süre karşılaştırıldığında genellikle hangi sonuç çıkar?', 'Kendi bildirimi daha uzun süre gösterir.', ['Cihaz ölçümü her zaman daha uzun süre gösterir.', 'İki ölçüm kusursuz biçimde örtüşür.', 'Kendi bildirimi yalnızca yaşlılarda daha yüksektir.'], 'İnsanlar beğenilen davranışları abartma ve kendini olumlu görme eğilimindedir. Nesnel ölçümler bu nedenle genellikle daha düşük değerler verir.'),
  ('Bir deneyde ilaç grubundan ayrılanların oranı %30, plasebo grubundan ayrılanların oranı %5\'tir. Bu fark en çok neye işaret edebilir?', 'Yan etkilerin katılımcıları uzaklaştırmış olabileceğine', ['Plasebo grubunun daha uzun süre izlendiğine', 'İlacın kesin olarak etkisiz olduğuna', 'Grupların rastgele atanmadığına ve bunun kesinlikle kanıtlandığına'], 'Gruplar arası farklı ayrılma oranları, ayrılmanın tedaviyle ilişkili olduğunu düşündürür. Bu durumda kalanlarla yapılan karşılaştırma yanlı olabilir.'),
  ('Kayıp yanlılığının etkisini değerlendirmek için araştırmacıların sıkça başvurduğu yöntem hangisidir?', 'Farklı varsayımlarla duyarlılık analizi yapmak', ['Ayrılanları hiç raporlamamak', 'Ayrılanların yerine yeni katılımcıları gizlice eklemek', 'Yalnızca çalışmayı tamamlayanların sonuçlarını ayrıntılı biçimde yayımlamak'], 'Duyarlılık analizi, eksik verilerin en kötü ve en iyi senaryolarında sonucun nasıl değiştiğini gösterir. Sonuç bu senaryolarda değişmiyorsa güven artar.'),
  ('Aynı okuldaki deney grubu öğrencilerinin yeni ders materyallerini kontrol grubundaki arkadaşlarıyla paylaşması hangi soruna yol açar?', 'Gruplar arası farkın küçülmesine', ['Deney grubunun örneklem büyüklüğünün artmasına', 'Kontrol grubunun sonuçlarının daha kötüleşmesine kesin olarak', 'Gruplar arası farkın yapay biçimde büyümesine'], 'Müdahalenin kontrol grubuna sızması (yayılma ya da bulaşma) iki grubu birbirine benzetir. Bu, gerçek etkinin olduğundan küçük ölçülmesine yol açar.'),
  ('Yarı deneysel bir çalışmada iki sınıf karşılaştırılıyor: bir sınıf yeni yöntemi, diğeri eski yöntemi uyguluyor. Sınıflardan biri seçmeli, diğeri zorunlu ders olarak açılmış. İç geçerlilik için en önemli tehdit hangisidir?', 'Grupların baştan farklı olması', ['Ölçme aracının değişmesi', 'Olgunlaşmanın yalnız bir grupta görülmesi', 'Ön testin hiç yapılmaması'], 'Dersi seçen öğrenciler ilgi ve motivasyon bakımından zorunlu dersi alanlardan farklı olabilir. Bu seçim tehdidi, sonuçtaki farkın yönteme bağlanmasını zorlaştırır.'),
  ('Bir araştırmanın bulgularının, gerçek dünyadaki koşullara ne ölçüde benzediğini ifade eden kavram aşağıdakilerden hangisidir?', 'Ekolojik geçerlilik', ['Yapı geçerliliği', 'Yordama geçerliliği', 'Kapsam geçerliliği'], 'Ekolojik geçerlilik, çalışma ortamı, görevleri ve uyaranlarının gündelik yaşama ne kadar yakın olduğunu sorgular; dış geçerliliğin bir yönüdür. Ekolojik yanılgıyla karıştırılmamalıdır.'),
  ('1990\'larda bir ülkede yapılmış bir eğitim deneyinin sonucunun bugün aynı biçimde geçerli olup olmadığı sorusu, dış geçerliliğin hangi boyutuyla ilgilidir?', 'Zamanlar arası genelleme', ['Kişiler arası (puanlayıcı) güvenirlik', 'İç tutarlılık', 'Ölçüm duyarlılığı'], 'Dış geçerlilik kişileri, ortamları ve zamanları kapsar. Teknoloji, müfredat ve toplumsal koşullar değiştikçe eski bulgular bugüne aktarılamayabilir.'),
  ('Yeni geliştirilen bir kaygı ölçeğinin puanları, kabul görmüş başka bir kaygı ölçeğiyle yüksek, matematik başarısıyla ise düşük korelasyon gösteriyor. Bu bulgular hangi kanıtı birlikte sağlar?', 'Birleşen ve ayırt edici geçerlilik', ['Yalnızca görünüş geçerliliği ve kapsam geçerliliği', 'Test-tekrar test güvenirliği', 'İç geçerlilik ve dış geçerlilik'], 'Aynı yapıyı ölçen araçla yüksek ilişki birleşen, ilgisiz yapıyla düşük ilişki ayırt edici geçerliliktir. Birlikte yapı geçerliliğini desteklerler.'),
  ('Bir araştırmacı "sosyal medya bağımlılığını" yalnızca günlük ekran süresiyle ölçüyor. Bu ölçümle ilgili en yerinde eleştiri hangisidir?', 'Yapının yalnız bir yönünü kapsadığı için yetersiz temsil eder.', ['Ekran süresi hiçbir zaman ölçülemez.', 'Ekran süresi ölçümü güvenirliği sıfıra indirir.', 'Ekran süresinin ölçülmesi dış geçerliliği kesin olarak artırır.'], 'Bağımlılık kontrol kaybı, yoksunluk ve işlevsellikte bozulma gibi boyutlar içerir. Yalnızca süreye bakmak yapıyı eksik temsil eder; bu yapı geçerliliği sorunudur.'),
  ('Üniversite giriş sınavı puanlarının öğrencilerin birinci sınıf not ortalamasıyla ilişkisinin incelenmesi hangi geçerlilik türüne örnektir?', 'Yordama geçerliliği', ['Görünüş geçerliliği', 'Kapsam geçerliliği', 'Uyum geçerliliği'], 'Yordama geçerliliği, puanların gelecekte ölçülecek bir ölçütü ne kadar iyi kestirdiğini gösterir. Ölçüt aynı anda ölçülseydi uyum (eş zamanlı) geçerliliği söz konusu olurdu.'),
  ('Bir kişilik ölçeğinin görünüş geçerliliği çok yüksek olduğunda, hangi istenmeyen durum ortaya çıkabilir?', 'Katılımcıların amacı sezip yanıtı çarpıtması', ['Ölçeğin hiç puanlanamaması', 'Kapsam geçerliliğinin kendiliğinden ve tamamen sıfırlanması', 'Ölçeğin yalnızca çocuklara uygulanabilmesi'], 'Neyin ölçüldüğü açıkça anlaşıldığında, özellikle işe alım gibi durumlarda kişiler kendilerini olumlu göstermek için yanıtlarını ayarlayabilir.'),
  ('Yeni ve kısa bir depresyon tarama testinin sonuçları, aynı hastalara aynı hafta yapılan klinik görüşme tanılarıyla karşılaştırılıyor. Bu çalışma hangi kanıtı sağlar?', 'Eş zamanlı ölçüt geçerliliği', ['Yordama geçerliliği', 'Görünüş geçerliliği', 'Test-tekrar test güvenirliği'], 'Ölçüt (klinik tanı) testle aynı zamanda belirlendiği için eş zamanlı ya da uyum geçerliliğidir. Ölçüt gelecekte ölçülseydi yordama geçerliliği olurdu.'),
  ('Bir zekâ testi yıllar boyunca aynı kişilere neredeyse aynı puanları veriyor; ancak puanlar okul başarısı ya da iş performansıyla hiç ilişkili değil. Bu test hakkında ne söylenebilir?', 'Tutarlıdır, ama zekâyı ölçtüğü kuşkuludur.', ['Geçerlidir, çünkü puanlar zamanla değişmemektedir.', 'Güvenilmezdir, çünkü başarıyla ilişkisizdir.', 'Hem güvenilmez hem de geçersizdir.'], 'Yüksek test-tekrar test tutarlılığı güvenirliği gösterir. Kuramsal olarak ilişkili olması gereken ölçütlerle ilişkinin olmaması geçerliliğe dair ciddi kuşku doğurur.'),
  ('Cronbach alfa katsayısı en çok hangi özelliği değerlendirmek için kullanılır?', 'Ölçek maddelerinin iç tutarlılığını', ['Ölçeğin zaman içindeki kararlılığını', 'İki puanlayıcının uyumunu', 'Ölçeğin gelecekteki başarıyı yordamasını'], 'Alfa, maddelerin aynı yapıyı birlikte ne ölçüde ölçtüğünü gösteren iç tutarlılık katsayısıdır. Zaman içindeki kararlılık için test-tekrar test kullanılır.'),
  ('Bir sınavın A ve B olmak üzere iki eşdeğer kitapçığı hazırlanmış ve aynı öğrencilere uygulanarak puanlar karşılaştırılmıştır. Bu işlem hangi güvenirliği verir?', 'Paralel formlar güvenirliği', ['Puanlayıcılar arası güvenirlik', 'İç tutarlılık güvenirliği', 'Yapı geçerliliği'], 'Paralel formlar güvenirliği, iki eşdeğer formun aynı özelliği tutarlı ölçüp ölçmediğini gösterir ve test etkisini azaltır.'),
  ('Bir kan basıncı çalışmasında hastaların yarısı sabah, yarısı akşam ölçülmüş ve gruplar ölçüm saatine göre ayrılmıştır. Kan basıncının gün içinde değiştiği bilindiğine göre bu durum ne yaratır?', 'Gruplar arasında sistematik bir ölçüm farkı', ['Yalnızca rastlantısal ve önemsiz bir dalgalanma', 'Puanlayıcılar arası güvenirlikte artış', 'Örneklem büyüklüğünde azalma'], 'Ölçüm koşulu gruplarla örtüştüğünde, ölçüm saatinden doğan fark grup farkı gibi görünür. Ölçüm koşulları gruplar arasında dengelenmelidir.'),
  ('Klasik test kuramına göre gözlenen puan hangi iki bileşenin toplamı olarak düşünülür?', 'Gerçek puan ve hata', ['Ortalama ve standart sapma', 'Ham puan ve yüzdelik', 'Madde güçlüğü ve madde ayırıcılığı'], 'Klasik test kuramında X = T + E, yani gözlenen puan gerçek puan ile ölçme hatasının toplamıdır. Güvenirlik, gözlenen varyansın gerçek puan varyansından gelen oranıdır.'),
  ('İki öğrencinin sınav puanları 74 ve 76\'dır; ölçmenin standart hatası 5 puandır. Bu iki öğrenci için hangi yorum en uygundur?', 'Fark ölçme hatası içinde kaldığı için anlamlı değildir.', ['76 alan öğrenci kesinlikle daha yeteneklidir.', '74 alan öğrenci kesinlikle daha yeteneklidir.', 'İki öğrencinin gerçek puanları tam olarak eşittir.'], '2 puanlık fark 5 puanlık ölçme hatasının çok altındadır. Bu nedenle iki öğrencinin gerçek düzeyleri arasında güvenilir bir sıralama yapılamaz.'),
  ('Bir çalışmada p = 0,03 bulunmuştur. Bu değerin doğru yorumu hangisidir?', 'H₀ doğruysa bu kadar uç bir sonucun olasılığı %3\'tür.', ['Sıfır hipotezinin doğru olma olasılığı %3\'tür.', 'Araştırma hipotezinin doğru olma olasılığı %97, yanlış olma olasılığı %3\'tür.', 'Sonucun tekrarlanma olasılığı %97\'dir.'], 'p-değeri, sıfır hipotezi varsayıldığında gözlenen ya da daha uç verinin olasılığıdır. Hipotezlerin doğru olma olasılığını doğrudan vermez.'),
  ('İki çalışmadan birinde p = 0,049, diğerinde p = 0,051 bulunmuştur. Bu sonuçlarla ilgili en makul değerlendirme hangisidir?', 'İki çalışmanın kanıt gücü neredeyse aynıdır.', ['Birinci çalışma etkiyi kanıtlamış, ikinci çalışma çürütmüştür.', 'İkinci çalışmanın etkisi birincisinden kesinlikle daha büyüktür.', 'Birinci çalışma, ikinci çalışmanın tersini göstermektedir.'], '0,05 çevresindeki küçük farklar kanıtta anlamlı bir ayrım yaratmaz. Sonuçları yalnızca "anlamlı/anlamsız" diye ikiye ayırmak yanıltıcıdır.'),
  ('Çok büyük bir örneklemde (n = 500.000) iki grubun ortalama boyları arasında 0,2 cm fark bulunmuş ve p < 0,001 çıkmıştır. Bu sonucun en doğru yorumu nedir?', 'Fark anlamlıdır ama pratikte önemsizdir.', ['Fark hem çok büyük hem de pratikte çok önemlidir.', 'Büyük örneklem p-değerini geçersiz kılar.', 'p < 0,001 olduğu için fark en az 10 cm olmalıdır.'], 'Örneklem çok büyüdüğünde küçücük farklar bile anlamlı çıkar. Anlamlılık, farkın büyüklüğü ya da önemi hakkında bilgi vermez; bunun için etki büyüklüğüne bakılır.'),
  ('Cohen\'in d etki büyüklüğü ölçüsü neyi ifade eder?', 'Ortalamalar farkının standart sapma cinsinden büyüklüğünü', ['Sıfır hipotezinin yanlış olma olasılığını', 'İki değişken arasındaki korelasyonun karesinin yüzde olarak ifadesini', 'Örneklemdeki kişi sayısının karekökünü'], 'Cohen\'in d\'si, ortalamalar farkını ortak standart sapmaya böler. Böylece farklı ölçeklerdeki çalışmaların etkileri karşılaştırılabilir.'),
  ('Küçük bir pilot çalışmada (n = 20) bir ders yönteminin etkisi d = 0,9 bulunmuş, ancak p = 0,07 çıkmıştır. Bu sonuç için en uygun yorum hangisidir?', 'Etki büyük görünse de kestirim belirsizdir; daha büyük çalışma gerekir.', ['Yöntemin hiçbir etkisinin olmadığı kanıtlanmıştır.', 'Etki büyük olduğu için kesin olarak kanıtlanmıştır.', 'p-değeri 0,05\'ten büyük olduğu için etki büyüklüğü hesaplanamaz ve yorumlanamaz.'], 'Küçük örneklemde etki kestirimleri çok oynaktır. Büyük bir d ile anlamsız bir p birlikte, sonucun hem önemli olabileceğini hem de belirsiz kaldığını gösterir.'),
  ('"Tedavi edilmesi gereken hasta sayısı" (NNT) 50 olan bir ilaç için hangi yorum doğrudur?', 'Bir olumsuz sonucu önlemek için 50 kişi tedavi edilmelidir.', ['Hastaların %50\'si ilaçtan yarar görür.', 'İlacı alan her 50 kişiden 49\'u iyileşir, yalnızca biri yarar görmez.', 'İlaç 50 gün kullanılmalıdır.'], 'NNT, mutlak risk azalmasının tersidir. NNT = 50, mutlak riskin 1/50 = 0,02 (iki yüzde puan) azaldığı anlamına gelir.'),
  ('Bir ilacın kalp krizi riskini mutlak olarak %4\'ten %3\'e düşürdüğü biliniyor. Tedavi edilmesi gereken hasta sayısı (NNT) kaçtır?', '100', ['25', '33', '4'], 'Mutlak risk azalması 0,04 − 0,03 = 0,01\'dir. NNT = 1 / 0,01 = 100\'dür.'),
  ('Bir ankette adayın oy oranı %48, %95 güven aralığı %45 ile %51 arasında bulunmuştur. Hangi yorum en doğrudur?', 'Yöntem tekrarlansa aralıkların yaklaşık %95\'i gerçek oranı içerir.', ['Seçmenlerin %95\'i bu adaya %45–51 arasında oy verecektir.', 'Adayın kesinlikle seçimi kaybedeceği kanıtlanmıştır.', 'Örneklemin %95\'i adaya oy vermiştir.'], 'Güven düzeyi, aralığı oluşturan yöntemin uzun dönemdeki başarı oranıdır. Aralık %50\'yi de içerdiği için adayın yarıyı geçip geçmediği belirsizdir.'),
  ('İki ilacın ağrıyı azaltma farkı için %95 güven aralığı (−0,5; 3,2) puan olarak verilmiştir. Bu aralık hakkında hangi çıkarım doğrudur?', 'Sıfır aralıkta olduğundan fark %5 düzeyinde anlamlı değildir.', ['İlaçlar arasında kesin olarak fark yoktur.', 'Birinci ilaç kesin olarak 3,2 puan daha etkilidir.', 'Fark %5 düzeyinde anlamlıdır, çünkü üst sınır sıfırdan büyüktür.'], 'Fark için güven aralığı sıfırı içeriyorsa sonuç o düzeyde anlamlı değildir. Ancak aralık 3,2 puana kadar uzandığı için anlamlı bir yarar olasılığı da dışlanamaz.'),
  ('Bir araştırmacı göreli risk için %95 güven aralığını (1,05; 4,80) buluyor. Bu sonuç için en dengeli yorum hangisidir?', 'Risk artışı anlamlıdır, ancak büyüklüğü belirsizdir.', ['Risk tam olarak 4,8 kat artmıştır.', 'Risk değişmemiştir, çünkü alt sınır 1\'e çok yakındır.', 'Maruziyet koruyucudur, çünkü aralık 1\'in altına iner.'], 'Göreli risk aralığı 1\'i içermediği için artış anlamlıdır. Ancak aralığın çok geniş olması gerçek etkinin çok küçük ya da çok büyük olabileceğini gösterir.'),
  ('Göreli risk ya da olasılık oranı için hesaplanan bir güven aralığında hangi değerin bulunması "anlamlı fark yok" demektir?', '1', ['0', '0,05', '100'], 'Oran ölçülerinde 1 değeri iki grubun riskinin eşit olduğunu gösterir. Fark ölçülerinde (ortalama farkı gibi) bu değer 0\'dır.'),
  ('Bir çalışmanın istatistiksel gücü 0,80 olarak hesaplanmıştır. Bu ne anlama gelir?', 'Gerçek bir etki varsa onu bulma olasılığı %80\'dir.', ['Sonucun doğru olma olasılığı %80\'dir.', 'Tip I hata olasılığı %80\'dir.', 'Katılımcıların %80\'inin tedaviden yarar göreceği ve sonucun bunu kanıtladığı'], 'Güç, gerçek bir etki varken sıfır hipotezinin reddedilme olasılığıdır; 1 − β olarak gösterilir. Bu örnekte Tip II hata olasılığı %20\'dir.'),
  ('Anlamlılık düzeyi 0,05\'ten 0,01\'e indirilirse, diğer her şey aynı kalmak koşuluyla ne olur?', 'Tip I hata azalır, Tip II hata artar.', ['Her iki hata olasılığı da azalır.', 'Tip I hata olasılığı artar, Tip II azalır.', 'Her iki hata olasılığı da artar.'], 'Daha katı bir eşik yanlış pozitifleri azaltır ama gerçek etkileri kaçırma riskini artırır. İkisini birlikte azaltmanın yolu örneklemi büyütmektir.'),
  ('Bonferroni düzeltmesinde 10 ayrı test yapılıyorsa ve genel hata düzeyi 0,05 tutulmak isteniyorsa, her test için hangi anlamlılık eşiği kullanılır?', '0,005', ['0,05', '0,5', '0,0005'], 'Bonferroni düzeltmesi alfa düzeyini test sayısına böler: 0,05 / 10 = 0,005. Bu yöntem basit ama oldukça tutucudur.'),
  ('Bir çalışmada ana analiz anlamsız çıkınca araştırmacılar katılımcıları yaşa, cinsiyete, bölgeye ve gelir düzeyine göre bölerek 16 alt grupta analiz yapıyor ve yalnızca "60 yaş üstü kadınlarda" etki buluyor. Bu bulgu için en doğru tutum hangisidir?', 'Yeni bir çalışmada sınanacak bir hipotez olarak görmek', ['Kesin bir bulgu olarak tedavi kılavuzlarına eklemek', 'Ana analizin yerine geçecek temel sonuç saymak', 'Yalnızca kadınlarla çalışmanın gerektiğinin kesin kanıtı olarak saymak'], 'Çok sayıda alt grup taramasında şans eseri bir anlamlı sonuç çıkması beklenir. Önceden planlanmamış alt grup bulguları keşifseldir ve doğrulanmalıdır.'),
  ('p-hackleme ve HARKing gibi sorunlara karşı geliştirilen "kayıtlı rapor" (registered report) modelinde dergi çalışmayı hangi aşamada kabul eder?', 'Veri toplanmadan, yöntem incelendikten sonra', ['Yalnızca sonuçlar anlamlı çıktıktan sonra', 'Veriler toplanıp analiz edildikten sonra', 'Çalışma başka dergilerce reddedildikten sonra'], 'Kayıtlı raporlarda yayın kararı soruya ve yönteme göre verilir. Böylece sonucun anlamlı çıkıp çıkmaması yayımlanmayı etkilemez.'),
  ('Keşifsel (keşif amaçlı) analiz ile doğrulayıcı analiz arasındaki doğru ayrım hangisidir?', 'Keşifsel analiz hipotez üretir, doğrulayıcı olan önceden kurulanı sınar.', ['Keşifsel analiz hipotezi kesin olarak kanıtlar.', 'Doğrulayıcı analiz yalnızca sonuçlar görüldükten sonra planlanır.', 'İkisi aynı kanıt gücüne sahiptir.'], 'Veriye bakarak bulunan örüntüler yeni hipotezlerin kaynağıdır. Bunları aynı veriyle "doğrulamak" döngüsel olur; bağımsız veriyle sınanmaları gerekir.'),
  ('Bir haber, "Yeni ilaç kalp krizi riskini %50 azaltıyor" diyor. Çalışmada kalp krizi oranı plasebo grubunda binde 2, ilaç grubunda binde 1\'dir. Mutlak risk azalması nedir?', '1.000 kişide 1', ['%50', '%1', '1.000 kişide 2'], 'Mutlak risk azalması iki grup arasındaki risk farkıdır: 0,002 − 0,001 = 0,001, yani binde 1. %50 ise göreli risk azalmasıdır.'),
  ('Göreli risk azalmasının mutlak risk azalmasına göre etkiyi daha çarpıcı göstermesinin nedeni nedir?', 'Başlangıç riskini göz ardı eder.', ['Her zaman daha büyük örneklemlerle hesaplanır.', 'Yalnızca anlamlı sonuçlar için hesaplanabilir.', 'Plasebo grubunu hesaba katmaz.'], 'Risk binde 2\'den binde 1\'e de, %40\'tan %20\'ye de inse göreli azalma %50\'dir. Mutlak fark ise ilk durumda çok küçüktür; bu nedenle ikisi birlikte raporlanmalıdır.'),
  ('1995\'te İngiltere\'de yeni nesil doğum kontrol haplarının pıhtı riskini "iki katına çıkardığı" duyurulunca pek çok kadın hapı bıraktı. Mutlak risk yaklaşık 7.000\'de 1\'den 7.000\'de 2\'ye çıkıyordu. Bu olaydan çıkarılacak ders nedir?', 'Yalnız göreli riskin duyurulması yanıltıcı olabilir.', ['Göreli risk her zaman mutlak riskten daha doğru bir ölçüdür.', 'İki katına çıkan riskler her zaman büyük risklerdir.', 'Pıhtı riskinin hiç değişmediği kanıtlanmıştır.'], '"İki kat" ifadesi korku yarattı; oysa mutlak artış çok küçüktü. Gerd Gigerenzer\'in aktardığı bu örnekte hapı bırakmak istenmeyen gebeliklere yol açtı.'),
  ('Bir doktor hastasına "Bu ilaç yan etki riskinizi %10\'dan %15\'e çıkarıyor" diyor. Hasta için bu bilginin "yan etki riski %50 artıyor" ifadesinden daha yararlı olmasının nedeni nedir?', 'Başlangıç riskini ve gerçek artışı birlikte gösterir.', ['Yüzde puan artışı her zaman daha küçük görünür.', 'Göreli risk tıpta kullanılmayan bir ölçüdür.', '%50 değeri yanlış hesaplanmıştır.'], 'Mutlak değerler hem başlangıç riskini hem de 5 yüzde puanlık artışı açıkça gösterir. Göreli ifade tek başına kişinin gerçek riskini anlamasını zorlaştırır.'),
  ('Havaalanında terörist taraması yapan bir sistem, teröristlerin %99\'unu yakalıyor ve masum yolcuların yalnızca %1\'ini yanlışlıkla işaretliyor. Yolcuların milyonda biri terörist olduğuna göre işaretlenen bir yolcu hakkında ne söylenebilir?', 'Büyük olasılıkla masumdur.', ['Neredeyse kesinlikle teröristtir.', 'Terörist olma olasılığı %99\'dur.', 'Terörist olma olasılığı %50\'dir.'], 'Bir milyon yolcuda yaklaşık 1 terörist ve 10.000 yanlış alarm olur. İşaretlenenlerin çok küçük bir kısmı gerçekten teröristtir.'),
  ('"Trafik kazalarında ölenlerin çoğu emniyet kemeri takıyordu, demek ki kemer işe yaramıyor" çıkarımındaki temel hata nedir?', 'Sürücülerin çoğunun zaten kemer taktığı unutulmuştur.', ['Kemer takanların hiç kaza yapmadığı varsayılmıştır.', 'Kaza sayısı yanlış hesaplanmıştır.', 'Kemerin yalnızca arka koltukta işe yaradığı unutulmuştur.'], 'Kemer takanlar sürücülerin büyük çoğunluğuysa, ölenler arasında da çoğunluk olmaları beklenir. Doğru karşılaştırma iki gruptaki ölüm oranlarıdır.'),
  ('Bir şirkette 9 çalışan aylık 30.000 TL, genel müdür ise 300.000 TL kazanıyor. Şirketin "ortalama maaşımız 57.000 TL" demesi hangi açıdan yanıltıcıdır?', 'Tek bir uç değer ortalamayı çok yukarı çekmektedir.', ['Ortalama yanlış hesaplanmıştır; doğrusu 30.000 TL\'dir.', 'Ortalama maaşlar her zaman medyandan düşük çıkar.', 'Genel müdürün maaşı ortalamaya katılamaz, bu yasaktır.'], '(9 × 30.000 + 300.000) / 10 = 57.000 TL\'dir ve hesap doğrudur. Ancak çalışanların %90\'ı 30.000 TL kazanır; bu durumda medyan daha temsilî bir ölçüdür.'),
  ('Bir veri setinde çok uç bir değer fark edildiğinde araştırmacının izlemesi gereken en uygun yol hangisidir?', 'Değerin hata mı gerçek mi olduğunu araştırıp gerekçeyle raporlamak', ['Sonucu beklentiye uyduracak biçimde değeri sessizce silmek', 'Değeri iki katına çıkararak analizi güçlendirmek', 'Uç değeri dikkate almadan yalnız ortalamayı raporlamak'], 'Uç değer bir giriş hatası olabileceği gibi önemli bir bilgi de olabilir. Karar sonuçlara bakılmadan, önceden belirlenmiş ölçütlerle verilmeli ve şeffaf biçimde bildirilmelidir.'),
  ('Bir ülkede ortalama hane geliri artarken medyan hane geliri değişmemiştir. Bu durum en çok neyi düşündürür?', 'Artışın en yüksek gelirli kesimde toplanmasını', ['Tüm hanelerin gelirinin eşit oranda artmasını', 'En düşük gelirli hanelerin gelirinin hızla artmasını', 'Hesaplamada hata yapıldığını kesin olarak'], 'Ortanca değer sabitken ortalamanın yükselmesi, üst uçtaki değerlerin büyüdüğünü gösterir. Ortanca hane bundan pay almamış olabilir.'),
  ('Bir çizgi grafiğinde zaman ekseni bazı yerlerde birer yıllık, bazı yerlerde beşer yıllık aralıklarla düzenlenmiş. Bu durum okuyucuyu nasıl yanıltabilir?', 'Değişim hızının dönemler arasında yanlış algılanmasına yol açar.', ['Grafiği daha doğru kılar, çünkü daha çok veri gösterir.', 'Yalnızca renklerin yanlış algılanmasına neden olur.', 'Veri noktalarının sayısını değiştirmez, bu nedenle etkisi yoktur.'], 'Eşit görünen aralıklar farklı sürelere karşılık geldiğinde eğimler karşılaştırılamaz hâle gelir. Eksen ölçeği tutarlı olmalıdır.'),
  ('Bir broşürde bir ülkenin askerî harcaması diğerinin iki katı olduğu için tank simgesi hem eni hem boyu iki katına çıkarılarak çizilmiştir. Bu çizim nasıl bir algı yaratır?', 'Farkı yaklaşık dört kat gösterir.', ['Farkı tam olarak iki kat gösterir.', 'Farkı yarı yarıya küçültür.', 'Farkın yönünü tersine çevirir.'], 'Eni ve boyu iki katına çıkan bir şeklin alanı dört katına çıkar. Göz alanı algıladığı için iki katlık fark dört kat gibi görünür.'),
  ('Bir şirket, toplam (birikimli) satış grafiği yayımlayarak satışlarının "hiç durmadan arttığını" söylüyor. Bu sunumun gizleyebileceği şey nedir?', 'Dönemlik satışların düşüyor olabileceğini', ['Şirketin toplam kaç ürün sattığını', 'Satışların para birimini', 'Grafiğin hangi yıl başladığını ve hangi yıl bittiğini'], 'Birikimli grafik, satış sıfırın üstünde kaldıkça hep yükselir. Dönemlik satışların azaldığını görmek için her dönemin satışına ayrı bakmak gerekir.'),
  ('Bir sunumda yalnızca 2019–2021 dönemi gösterilerek bir göstergenin "hızla düştüğü" sunuluyor; oysa 1990\'dan beri bakıldığında gösterge dalgalanarak yükselmiştir. Bu sunum hangi hatayı içerir?', 'Zaman aralığının seçici kullanılması', ['Eksenin sıfırdan başlatılması', 'Verilerin yüzdelere dönüştürülmesi', 'Ortalamanın yerine medyanın kullanılması'], 'Başlangıç ve bitiş noktalarını seçmek eğilimi istenen yöne çevirebilir. Uzun dönemli bağlam verilmeden yapılan yorumlar yanıltıcıdır.'),
  ('Pasta grafiklerle ilgili hangi durum okuyucuyu yanıltabilir?', 'Dilimlerin toplamının %100\'ü aşması', ['Dilimlerin farklı renkte boyanması', 'Dilimlerin etiketlerinin yazılması', 'En büyük dilimin üstten başlatılması'], 'Pasta grafik bir bütünün parçalarını gösterir; toplamı %100\'ü aşıyorsa (örneğin birden çok seçeneğin işaretlenebildiği sorularda) bu biçim uygun değildir.'),
  ('Bir kasabada hırsızlık olayı 2 iken ertesi yıl 4 olmuş ve haber "Hırsızlık %100 arttı!" diye duyurulmuştur. Bu başlığın yanıltıcılığı nereden kaynaklanır?', 'Küçük sayılardaki değişimin büyük bir yüzdeyle sunulmasından', ['Yüzdenin yanlış hesaplanmasından, çünkü artış %50\'dir', 'Hırsızlık sayısının yüzdeyle hiç ifade edilememesinden', 'Artışın aslında azalma olmasından'], '2\'den 4\'e çıkış gerçekten %100 artıştır; ancak 2 olaylık fark şans eseri de oluşabilir. Küçük tabanlarda yüzdeler dramatik ama bilgi değeri düşük olur.'),
  ('"Kazaların çoğu evden 5 km\'den yakın yerde oluyor, öyleyse evin yakınında araç kullanmak daha tehlikeli" çıkarımının temel hatası nedir?', 'Yolculukların çoğunun ev yakınında yapıldığı unutulmuştur.', ['Kaza sayılarının yanlış kaydedilmesi', 'Uzak yolculukların hiç kaza içermediği varsayımının veriyle çelişmesi', 'Mesafelerin kilometreyle ölçülmesi'], 'Kaza sayısı, o bölgede ne kadar yol yapıldığına bağlıdır. Risk karşılaştırması için kilometre başına düşen kaza oranı gerekir.'),
  ('Bir ilaç deneyinde "ilacı alanlardan 15 kişi iyileşti" bilgisi verilmiştir. Bu bilgiyi değerlendirebilmek için en az hangi iki bilgiye ihtiyaç vardır?', 'Grup büyüklüğü ve karşılaştırma grubundaki iyileşme', ['İlacın rengi ve kutu boyutu', 'Deneyi yürüten kurumun adı, adresi ve kuruluş tarihi', 'İyileşenlerin isimleri ve doğum yerleri'], 'Kaç kişiden 15\'inin iyileştiği ve ilaç almayanların ne kadar iyileştiği bilinmeden, bu sayı etkililik hakkında hiçbir şey söylemez.'),
  ('Bir ülkede kanser tanısı konan kişi sayısı 30 yılda iki katına çıkmıştır. Bu artışı "kanser salgını" olarak yorumlamadan önce hangi etkenler hesaba katılmalıdır?', 'Nüfus artışı, yaşlanma ve tanı yöntemlerinin gelişmesi', ['Hastanelerin binalarının yenilenmesi', 'Kanser ilaçlarının fiyatı', 'Kanser hakkında yazılan kitapların ve haberlerin sayısındaki artış'], 'Nüfus artışı ve yaşlanma vaka sayısını kendiliğinden artırır; tarama programları ise daha çok tanı koydurur. Yaşa göre standartlaştırılmış oranlar karşılaştırma için gereklidir.'),
  ('Bir ürün reklamında "Kullanıcıların %90\'ı memnun" yazıyor; dipnotta bu oranın ürünü üç yıldır kullanan 20 kişilik bir gruptan geldiği belirtiliyor. Bu bilgi oranın değerini nasıl etkiler?', 'Memnun olanların seçildiği küçük bir grup olduğu için oranı çok zayıflatır.', ['Oranın kesin olarak doğru olduğunu ve genellenebileceğini kanıtlar.', 'Oranı etkilemez, çünkü yüzdeler örneklemden bağımsızdır.', 'Oranı güçlendirir, çünkü uzun süreli kullanıcılar uzmandır.'], 'Ürünü üç yıl kullanmaya devam edenler zaten memnun olanlardır. Hem seçim hem de küçük örneklem bu oranı tüm kullanıcılar için anlamsız kılar.'),
  ('Bir siyasetçi, "Bilim insanları bu maddenin kansere yol açabileceğini söylüyor" diyerek yalnızca fareler üzerindeki yüksek dozlu tek bir çalışmaya dayanıyor. Bu kanıt kullanımının temel sorunu nedir?', 'Tek ve sınırlı bir çalışma bağlamından koparılarak genelleştirilmiştir.', ['Fare deneyleri hiçbir koşulda insanlarla ilgili bilgi veremez ve hep yanlıştır.', 'Bilim insanlarının görüşü hiç önemli değildir.', 'Kanser bilimsel olarak incelenemeyen bir konudur.'], 'Hayvan çalışmaları ve yüksek dozlar insanlardaki gerçek maruziyeti temsil etmeyebilir. Kanıtın bütünü ve bağlamı verilmeden tek çalışma öne çıkarılmamalıdır.'),
  ('İnsanların tek bir canlı hikâyeyi, binlerce kişiyi kapsayan istatistiklerden daha ikna edici bulması hangi bilişsel eğilimle ilişkilidir?', 'Erişilebilirlik sezgisi', ['Simpson paradoksu ve buna bağlı birleştirme hatası', 'Ortalamaya dönüş', 'Tip II hata'], 'Kolayca akla gelen, duygusal ve somut örnekler olasılık yargılarını orantısız biçimde etkiler. Tversky ve Kahneman bu eğilimi erişilebilirlik sezgisi olarak tanımlamıştır.'),
  ('Uçak kazalarının haberlerde geniş yer bulması nedeniyle insanların uçak yolculuğunu karayolundan daha tehlikeli sanması neyi gösterir?', 'Medyada görünürlüğün risk algısını çarpıttığını', ['Uçak yolculuğunun kilometre başına karayolundan çok daha tehlikeli olduğunu', 'Karayolu kazalarının kaydedilmediğini', 'Risk algısının istatistiklerle her zaman örtüştüğünü'], 'Nadir ama çarpıcı olaylar belleğe kolay yerleşir. Kilometre başına ölüm oranları ise ticari uçuşların karayolundan çok daha güvenli olduğunu gösterir.'),
  ('Bir ilçede 5 bebeğin doğduğu bir hastanede bir gün doğan bebeklerin %80\'i kız, 500 bebeğin doğduğu büyük bir hastanede ise %52\'si kız çıkmıştır. Bu farkın en olası açıklaması nedir?', 'Küçük örneklemlerde oranlar şans eseri çok daha fazla dalgalanır.', ['Küçük hastanenin bulunduğu bölgede genetik olarak daha çok kız doğar.', 'Büyük hastanede kayıtlar yanlış tutulmuştur.', 'Küçük hastanede doğum yöntemleri farklıdır.'], '5 doğumda 4 kız çıkması kolayca şansla olabilir; 500 doğumda ise oran %50\'ye yakın kalır. Kahneman ve Tversky\'nin hastane problemine benzeyen bu durum küçük sayılar yasası yanılgısını gösterir.'),
  ('2015 yılında Open Science Collaboration\'ın psikolojideki 100 çalışmayı yeniden yaptığı projede genel bulgu ne olmuştur?', 'Tekrarlarda anlamlı sonuç ve etki büyüklüğü belirgin biçimde daha düşük çıktı.', ['Çalışmaların tamamı aynı etki büyüklüğüyle eksiksiz olarak tekrarlandı.', 'Hiçbir çalışma tekrarlanamadı.', 'Tekrarlarda etkiler iki katına çıktı.'], 'Özgün çalışmaların yaklaşık %97\'si anlamlıyken tekrarların yaklaşık %36\'sı anlamlı sonuç verdi ve etkiler ortalamada yarıya yakın küçüldü. Bu, "tekrarlanabilirlik krizi" tartışmasını büyüttü.'),
  ('2011\'de bir psikoloğun yayımladığı ve insanların geleceği önceden sezebildiğini öne süren çalışmalar, bağımsız tekrarlarda doğrulanamamıştır. Bu durum bilimsel süreç hakkında neyi gösterir?', 'Tek bir yayının, ne kadar saygın olsa da, kesin kanıt sayılmaması gerektiğini', ['Saygın dergilerde yayımlanan her bulgunun kesinlikle doğru olduğunu ve sorgulanamayacağını', 'Tekrar çalışmalarının bilimsel bir değeri olmadığını', 'Geleceği sezme yeteneğinin kanıtlandığını'], 'Daryl Bem\'in çalışmaları, standart yöntemlerle bile şaşırtıcı yanlış pozitiflerin yayımlanabileceğini gösterdi ve yöntem tartışmalarını hızlandırdı.'),
  ('Sistematik derlemeyi sıradan bir literatür derlemesinden ayıran temel özellik nedir?', 'Önceden belirlenmiş, açık ve tekrarlanabilir bir tarama ve seçim yöntemi', ['Yazarın en çok beğendiği ve kendi görüşünü destekleyen çalışmaları seçmesi', 'Yalnızca tek bir çalışmanın ayrıntılı özeti olması', 'Hiçbir kaynakça içermemesi'], 'Sistematik derlemede arama stratejisi, dahil etme ölçütleri ve değerlendirme yöntemi önceden tanımlanır. Bu, seçici kaynak kullanımı yanlılığını azaltır.'),
  ('Bir meta-analiz, çok farklı yöntemlerle yürütülmüş ve düşük kaliteli on çalışmayı birleştirerek kesin bir etki buluyor. Bu sonuç için en uygun eleştiri hangisidir?', 'Zayıf çalışmaları birleştirmek, yanlılıklarını ortadan kaldırmaz.', ['Meta-analizler yalnızca iki çalışmayla ve aynı yazarlarca yapılabilir.', 'Çalışma sayısı arttıkça sonuç her zaman yanlış olur.', 'Düşük kaliteli çalışmalar etkiyi hiçbir zaman değiştirmez.'], '"Çöp girerse çöp çıkar" ilkesi gereği, sistematik hatalar birleştirildiğinde de korunur. Çalışma kalitesi ve heterojenlik değerlendirilmelidir.'),
  ('Bir meta-analizde her çalışmanın genel sonuca katkısı genellikle neye göre ağırlıklandırılır?', 'Kestirimin kesinliğine', ['Çalışmanın yayımlandığı derginin kapak tasarımına ve sayfa sayısına', 'Yazarların sayısına', 'Çalışmanın yayım yılının tek ya da çift olmasına'], 'Daha büyük ve kesin çalışmalar daha küçük varyansa sahiptir ve ters varyans ağırlıklandırmasıyla genel kestirimde daha çok söz sahibi olur.'),
  ('Bir aşı kampanyasından birkaç hafta sonra bazı çocuklarda bir rahatsızlık tanısı konması, aşının bu rahatsızlığa yol açtığını göstermez. Bunu değerlendirmek için hangi karşılaştırma gerekir?', 'Aşılanan ve aşılanmayan çocuklarda rahatsızlığın sıklığı', ['Rahatsızlık tanısı konan çocukların aşı kartlarındaki imza sayısı ve renkleri', 'Aşının üretildiği fabrikanın yeri', 'Kampanyanın kaç gün sürdüğü'], 'Bazı rahatsızlıklar doğal olarak belirli yaşlarda ortaya çıkar ve aşı takvimiyle çakışabilir. Yalnız iki grubun oranları karşılaştırılarak nedensellik değerlendirilebilir.'),
  ('Bir kişinin önce ahırın duvarına rastgele ateş edip sonra mermilerin en yoğun olduğu yerin çevresine hedef çizmesi benzetmesiyle anlatılan yanılgı hangisidir?', 'Teksas keskin nişancı yanılgısı', ['Kumarbaz yanılgısı ve buna bağlı sıcak el inancı', 'Saman adam yanılgısı', 'Taban oranı yanılgısı'], 'Bu yanılgıda örüntü veriye bakıldıktan sonra tanımlanır ve şans eseri kümelenmeler anlamlı sanılır. Hipotez veriden önce kurulmalıdır.'),
  ('Bir ülkede kanser vakalarının harita üzerinde bir kasabada yoğunlaştığı fark ediliyor ve yakındaki bir baz istasyonu suçlanıyor. Teksas keskin nişancı yanılgısı açısından hangi uyarı yerindedir?', 'Rastgele dağılımda da bazı yerlerde kümelenme beklenir.', ['Kanser vakaları her zaman eşit dağılır ve kümelenme hiç görülmez, bu kesindir.', 'Baz istasyonları her zaman kansere yol açar.', 'Haritalar hastalık verisi göstermek için kullanılamaz.'], 'Pek çok bölgede vaka sayısına bakıldığında bazılarının şans eseri yüksek çıkması olağandır. Kümelenme bulunduktan sonra neden aramak yerine önceden kurulmuş bir hipotez sınanmalıdır.'),
  ('Yeni bir müdür göreve geldikten sonra şirketin kârı artınca basın bunu müdürün başarısı olarak sunuyor. Hangi bilgi bu yorumu en çok zayıflatır?', 'Aynı dönemde sektördeki bütün şirketlerin kârının benzer biçimde artması', ['Müdürün göreve başladığı günün haftanın hangi gününe denk geldiği', 'Müdürün eğitim aldığı üniversite', 'Şirketin logosunun renginin değişmesi'], 'Sektör genelindeki artış, kârdaki yükselişin müdürden bağımsız ortak bir nedene (ekonomik koşullar) bağlı olabileceğini gösterir.'),
  ('Bir eğitim programının başarıya etkisi, öğrencilerin özgüveninin artmasıyla açıklanıyor. Bu iddiayı sınamak için araştırmacı neyi göstermelidir?', 'Programın özgüveni, özgüvenin de başarıyı artırdığını', ['Özgüvenin programdan önce ölçüldüğünü ve programla hiç değişmediğini, yani sabit kaldığını', 'Programın yalnızca başarısız öğrencilere uygulandığını', 'Özgüvenin başarıyla hiç ilişkili olmadığını'], 'Aracılık iddiası iki halkalı bir zincir gerektirir: müdahale aracıyı, aracı da sonucu etkilemelidir. Zincirin bir halkası eksikse aracılık desteklenmez.'),
  ('Ağır depresyon hastalarının çoğunun ölçeğin en düşük işlevsellik puanını aldığı bir çalışmada, bir tedavinin daha da kötüleşmeyi önleyip önlemediğini değerlendirmek neden zordur?', 'Taban etkisi kötüleşmenin ölçülmesini engeller.', ['Tavan etkisi iyileşmenin ölçülmesini engeller ve ortalamayı yükseltir.', 'Puanların çok dağınık olması güvenirliği sıfıra indirir.', 'Ölçek iç tutarlılığını kaybeder.'], 'Katılımcılar zaten ölçeğin en alt ucundaysa daha kötü bir durumu gösterecek puan kalmaz. Ölçek bu bölgede ayırt edici değildir.'),
  ('Bir şehirde suç oranı 10 yıl boyunca düzenli olarak düşerken yeni bir yasa yürürlüğe giriyor ve düşüş aynı hızla sürüyor. Yasanın etkisi hakkında hangi yorum en doğrudur?', 'Düşüş yasadan önce başladığı için yasanın etkisi belirsizdir.', ['Düşüşün tamamı yasaya bağlanır, çünkü yasadan sonra da sürmüştür ve bu kesin kanıttır.', 'Yasa suçu artırmıştır.', 'Suç oranları zamanla değişmez.'], 'Önceden var olan bir eğilimin devam etmesi, yasanın ek bir etkisini göstermez. Yasanın etkisi için eğilimde bir kırılma ya da karşılaştırma grubu gerekir.'),
  ('Bir hastalığın vaka sayıları hafta sonları düşük, pazartesi günleri yüksek bildiriliyor. Bu örüntünün en olası açıklaması nedir?', 'Raporlamanın hafta sonu gecikmesi', ['Hastalığın virüsünün hafta sonları biyolojik olarak dinlenmesi ve etkisini yitirmesi', 'Pazartesi günlerinin daha soğuk olması', 'Hafta sonlarında insanların bağışıklığının güçlenmesi'], 'Laboratuvar ve kayıt sistemleri hafta sonu daha az çalışınca vakalar sonraki günlere aktarılır. Bu, gerçek bir değişim değil bildirim örüntüsüdür.'),
  ('Bir hastane, acil serviste dört saat içinde ilgilenilen hasta oranını performans ölçütü yapınca bazı hastaların ambulansta bekletilerek saatin geç başlatıldığı ortaya çıkıyor. Bu durum hangi ilkeyi örnekler?', 'Göstergenin hedef olunca asıl amaçtan kopması', ['Ortalamaya dönüşün hastane kayıtlarına yansıması', 'Hayatta kalan yanlılığının hasta seçimini bozması', 'Tavan etkisinin bekleme süresini sınırlaması'], 'Ölçüt hedef hâline gelince, hasta bakımını iyileştirmek yerine ölçütü iyi gösterecek davranışlar ortaya çıkmıştır. Bu Goodhart yasasının tipik bir örneğidir.'),
  ('Okulların yalnızca sınav ortalamalarına göre ödüllendirildiği bir sistemde hangi istenmeyen sonuç ortaya çıkabilir?', 'Öğretimin sınava yönelik daralması', ['Sınav ortalamalarının hesaplanamaz hâle gelmesi', 'Öğretmenlerin sınavları hiç uygulamaması', 'Öğrenci sayısının kendiliğinden artması'], 'Kurumlar, sınav puanını yükselten ama geniş öğrenmeyi daraltan stratejilere yönelebilir. Toplumsal bir göstergenin karar için kullanıldıkça bozulmasına Campbell yasası da denir.'),
  ('Goodhart yasasının olumsuz etkilerini azaltmak için en uygun yaklaşım hangisidir?', 'Birden çok tamamlayıcı gösterge kullanıp bunları gözden geçirmek', ['Tek bir göstergeyi seçip onu olabildiğince yüksek parasal ödüllerle hedeflemek', 'Hiçbir ölçme yapmamak', 'Göstergeleri çalışanlardan gizleyerek ölçümü tamamen gizli tutmak'], 'Tek bir sayı kolayca oyuna getirilebilir. Farklı yönleri ölçen göstergeler ve nitel değerlendirme, ölçütün asıl amaçtan sapmasını zorlaştırır.'),
  ('Bir veri setinde x arttıkça y\'nin de arttığı ama ilişkinin doğrusal değil, sürekli artan sıralı bir ilişki olduğu görülüyor. Bu durumda Pearson yerine hangi katsayı daha uygun olabilir?', 'Spearman sıra korelasyonu', ['Cronbach alfa katsayısı', 'Cohen kappa katsayısı', 'Varyasyon katsayısı'], 'Spearman katsayısı değerlerin sıralarına dayanır ve tek yönlü (monoton) ama doğrusal olmayan ilişkileri de yakalar. Aykırı değerlere de daha az duyarlıdır.'),
  ('"Oksijen yanma için gereklidir ama tek başına yangın çıkarmaz" ifadesi nedensellikteki hangi ayrımı örnekler?', 'Gerekli ama yeterli olmayan neden', ['Yeterli ama gerekli olmayan neden', 'Ne gerekli ne yeterli neden', 'Hem gerekli hem de tek başına yeterli neden'], 'Oksijen olmadan yanma olmaz, bu yüzden gereklidir. Ancak yakıt ve tutuşma sıcaklığı da gerektiği için tek başına yeterli değildir.'),
  ('Bir deneyde kontrol grubuna düşen katılımcılar, kendilerine değerli bir uygulamanın verilmediğini öğrenince motivasyonlarını kaybediyor ve performansları düşüyor. Bu durum deney sonucunu nasıl etkiler?', 'Müdahalenin etkisi olduğundan büyük görünür.', ['Müdahalenin etkisi olduğundan küçük ve önemsiz görünür.', 'Müdahalenin etkisi tam olarak doğru ölçülür.', 'Sonuçların yönü tersine döner.'], 'Kontrol grubunun moral bozukluğuyla gerilemesi (kırgın moral bozulması) gruplar arası farkı yapay olarak artırır.'),
  ('Bir sınıfın sınav puanlarının ortalaması 60, standart sapması 10\'dur. Puanlar yaklaşık normal dağılıyorsa öğrencilerin yaklaşık yüzde kaçı 50 ile 70 arasında puan almıştır?', '%68', ['%95', '%50', '%99,7'], 'Normal dağılımda değerlerin yaklaşık %68\'i ortalamanın bir standart sapma altı ile üstü arasında yer alır; burada 50–70 aralığıdır.'),
  ('Bir öğrencinin matematikte z = 1,2, Türkçede z = 0,4 puanı vardır. Bu bilgi neyi gösterir?', 'Matematikte sınıfına göre daha üst bir konumdadır.', ['Türkçe ham puanı matematikten kesin olarak yüksektir.', 'İki derste de sınıf ortalamasının altındadır.', 'Matematikte sınıfın tam ortasındadır.'], 'z puanı, kişinin kendi grubunun ortalamasına göre kaç standart sapma uzakta olduğunu gösterir. Farklı ölçekteki sınavları karşılaştırmaya olanak tanır.'),
  ('Haftalık çalışma saati (x) ile sınav puanı (y) arasındaki regresyon denklemi y = 40 + 3x olarak bulunmuştur. Eğimin doğru yorumu nedir?', 'Bir saat fazla çalışma ortalama 3 puan yüksek puanla ilişkilidir.', ['Hiç çalışmayan bir öğrenci 3 puan alır.', 'Her öğrenci tam olarak 43 puan alır.', 'Bir saat fazla çalışmak her öğrencinin puanını kesin olarak 3 puan artırır.'], 'Eğim, x\'teki bir birimlik farkın y\'de ortalama ne kadar farkla ilişkili olduğunu gösterir. Gözlemsel veride bu ilişki nedensel bir artış garantisi vermez.'),
  ('Bir araştırmacı, 30 gözlemli bir veri setine 25 açıklayıcı değişkenli bir regresyon modeli kuruyor ve R² = 0,98 buluyor. Bu sonuç için en uygun değerlendirme hangisidir?', 'Değişken sayısı gözleme göre çok fazladır; uyum yanıltıcıdır.', ['Model kusursuzdur ve yayımlanmalıdır.', 'R² yüksek olduğu için değişkenler arasındaki nedensellik kesin olarak kanıtlanmıştır.', 'R² 1\'e yakın olduğunda aşırı uyum olamaz.'], 'Değişken sayısı gözlem sayısına yaklaştıkça R² kendiliğinden yükselir. Böyle bir model büyük olasılıkla gürültüyü öğrenmiştir ve yeni veride başarısız olur.'),
  ('Bir ankette gelir sorusunu yanıtlamayanların büyük kısmının çok yüksek gelirli kişiler olduğu biliniyor. Yanıt verenlerin ortalama gelirini tüm katılımcıların ortalaması saymak nasıl bir sonuç verir?', 'Ortalama gerçekte olduğundan düşük kestirilir.', ['Ortalama gerçekte olduğundan yüksek kestirilir.', 'Kestirim tamamen yansız olur.', 'Ortalama hesaplanamaz.'], 'Eksiklik değerin kendisiyle ilişkiliyse (rastgele olmayan eksiklik) yalnız tam yanıtları kullanmak yanlılık yaratır. Burada yüksek gelirler eksik olduğundan ortalama aşağı kayar.'),
  ('Bir şehirde ağaç sayısı fazla olan mahallelerde astım oranının daha düşük olduğu bulunmuştur. Bu ilişkiyi nedensel saymadan önce sorulması gereken en önemli soru hangisidir?', 'Ağaçlı mahallelerin gelir ve trafikte farklı olup olmadığı', ['Ağaçların hangi türden olduğu, kaç yaşında olduğu ve kim tarafından dikildiği', 'Astımın hangi yıl tanımlandığı', 'Mahallelerin adlarının ne olduğu'], 'Ağaçlı mahalleler daha zengin ve trafikten uzak olabilir; bu etkenler astımı da etkiler. Karıştırıcılar dışlanmadan ağaçların koruyucu olduğu söylenemez.'),
  ('Kahvaltı yapan çocukların okulda daha başarılı olduğu gözlenmiştir. Aşağıdaki çalışma tasarımlarından hangisi kahvaltının başarıya etkisini en güçlü biçimde sınar?', 'Rastgele seçilen sınıflara ücretsiz kahvaltı verip karşılaştırmak', ['Kahvaltı yapan ve yapmayan çocukların notlarının bir kez karşılaştırılması', 'Ailelere kahvaltının önemini soran bir anket yapılması', 'Başarılı öğrencilerin kahvaltı alışkanlıklarının sorulması'], 'Rastgele atama, aile geliri ve ilgisi gibi karıştırıcıları gruplar arasında dengeler. Diğer tasarımlar yalnızca ilişkiyi gösterir.'),
  ('Uyku süresi kısa olan gençlerin daha çok depresyon belirtisi gösterdiği bulunmuştur. Hangi açıklama ters nedenselliği ifade eder?', 'Depresyonun uykuyu bozması', ['Kısa uykunun depresyona yol açması', 'Ekran kullanımının hem uykuyu hem ruh hâlini etkilemesi', 'İlişkinin şans eseri bulunması'], 'Ters nedensellik, varsayılan sonucun aslında neden olmasıdır. Depresyon uykusuzluğa yol açıyorsa ilişki ters yöndedir; ekran kullanımı ise karıştırıcı açıklamadır.'),
  ('Basketbolda arka arkaya birkaç atışı isabet ettiren oyuncunun bir sonraki atışı da sokma olasılığının arttığına dair yaygın inanca ne ad verilir?', 'Sıcak el inancı', ['Kumarbaz yanılgısı', 'Taban oranı yanılgısı', 'Ekolojik yanılgı'], 'Gilovich, Vallone ve Tversky\'nin 1985 çalışması, izleyicilerin rastlantısal dizilerdeki seriler için fazla anlam yüklediğini öne sürdü. Sonraki çalışmalar küçük bir gerçek etki olabileceğini tartışmıştır.'),
  ('Bir öğrencinin üç dersten ortalaması şöyledir: 2 kredilik derste 90, 4 kredilik derste 60, 4 kredilik derste 70. Kredilere göre ağırlıklı ortalaması kaçtır?', '70', ['73,3', '75', '66'], '(2 × 90 + 4 × 60 + 4 × 70) / 10 = (180 + 240 + 280) / 10 = 70\'tir. Basit ortalama ise 73,3 olurdu; ağırlıklar farklıysa basit ortalama yanıltır.'),
  ('A okulunda 20 öğrencinin ortalaması 80, B okulunda 180 öğrencinin ortalaması 60\'tır. İki okulun birlikte öğrenci ortalaması için "(80 + 60) / 2 = 70" hesabının hatası nedir?', 'Okullar farklı büyüklükte olduğu için ağırlıklı ortalama gerekir.', ['Ortalamalar hiçbir koşulda birleştirilemez.', 'Hesap doğrudur, okul sayısı ikidir.', 'Ortalama yerine en yüksek puan kullanılmalıdır.'], 'Doğru ortalama (20 × 80 + 180 × 60) / 200 = 62\'dir. Ortalamaların ortalamasını almak küçük grubun etkisini abartır.'),
  ('Bir tarama testinin özgüllüğü %95\'tir. 1.000 sağlıklı kişi test edildiğinde yaklaşık kaç kişide yanlış pozitif sonuç beklenir?', '50', ['950', '5', '95'], 'Özgüllük, sağlıklıları doğru biçimde negatif bulma oranıdır. %95 özgüllükte sağlıklıların %5\'i, yani 1.000\'de 50 kişi yanlışlıkla pozitif çıkar.'),
  ('Hastalığın çok nadir olduğu bir toplumda negatif test sonucu için hangi yorum genellikle doğrudur?', 'Negatif sonuç hastalığı büyük olasılıkla dışlar.', ['Negatif sonuç büyük olasılıkla yanlıştır.', 'Negatif sonucun hiçbir bilgi değeri yoktur.', 'Negatif sonuç kişinin kesin olarak hasta olduğunu gösterir.'], 'Yaygınlık düşükken test öncesi hastalık olasılığı zaten çok küçüktür. Bu nedenle negatif kestirim değeri çok yüksek olur.'),
  ('Bir araştırmada yanlılıklar genellikle üç ana grupta toplanır. Aşağıdakilerden hangisi bu sınıflamaya uygundur?', 'Seçim yanlılığı, bilgi yanlılığı, karıştırıcılık', ['Ortalama, medyan ve mod', 'Tip I hata, Tip II hata ve güç', 'Güvenirlik, geçerlilik, kullanışlılık ve ekonomiklik'], 'Epidemiyolojide sistematik hatalar katılımcı seçimi (seçim), ölçüm ya da sınıflandırma (bilgi) ve ortak nedenler (karıştırıcılık) olarak sınıflanır.'),
  ('Bir çalışmada hastalar ve sağlıklılar farklı yöntemlerle sorgulanmıştır: hastalar ayrıntılı yüz yüze görüşmeyle, sağlıklılar kısa bir telefon görüşmesiyle. Bu durum hangi tür yanlılığa girer?', 'Bilgi yanlılığı', ['Seçim yanlılığı', 'Yayın yanlılığı', 'Hayatta kalan yanlılığı'], 'Gruplardan bilgi toplama biçiminin farklı olması, maruziyetin bir grupta daha eksiksiz kaydedilmesine yol açar. Bu ölçümden kaynaklanan bir bilgi (ölçüm) yanlılığıdır.'),
  ('Bir kohort çalışmasında 1.000 sigara içenden 30\'unda, 1.000 içmeyenden 10\'unda hastalık gelişmiştir. Atfedilen risk (risk farkı) kaçtır?', '1.000 kişide 20', ['1.000 kişide 3', '1.000 kişide 40', '1.000 kişide 30'], 'Risk farkı = 30/1.000 − 10/1.000 = 20/1.000\'dir. Göreli risk ise 3\'tür; iki ölçü birbirini tamamlar.'),
  ('Fransız fizikçi René Blondlot 1903\'te "N-ışınları" adını verdiği yeni bir ışınım keşfettiğini duyurmuş, pek çok araştırmacı da bu ışınları gözlediğini bildirmiştir. Robert Wood\'un ziyareti sırasında düzenekteki prizmayı gizlice çıkarmasına rağmen Blondlot\'un ışınları görmeye devam etmesi neyi göstermiştir?', 'Gözlemlerin beklentiden kaynaklandığını', ['N-ışınlarının prizmasız da var olduğunu', 'Wood\'un düzeneği bozduğunu ve deneyi geçersiz kıldığını', 'Işınların yalnızca Fransa\'da görülebildiğini'], 'Prizma olmadan sonuç değişmemesi, gözlemlerin fiziksel bir olguya değil gözlemcinin beklentisine dayandığını ortaya koydu. Bu, körlemenin önemini gösteren klasik bir örnektir.'),
  ('Richard Doll ve Austin Bradford Hill\'in 1950\'de yayımladığı vaka-kontrol çalışmasında, akciğer kanserli hastaların sigara içme oranının kontrol grubundan yüksek olduğu bulunmuştur. Bu tür bir tasarımın tek başına nedenselliği kesinleştirememesinin başlıca nedeni nedir?', 'Gözlemsel olduğu için karıştırıcılar dışlanamaz.', ['Sigara içme alışkanlığının hastalara hiç sorulmamış olması', 'Çalışmanın yalnızca iki hastayı içermesi', 'Kanserin o dönemde teşhis edilememesi'], 'Vaka-kontrol tasarımı ilişkiyi güçlü biçimde gösterdi; ancak nedensellik, sonraki kohort çalışmaları (İngiliz hekimler çalışması), doz-yanıt ve tutarlılık gibi kanıtların birikmesiyle kabul gördü.'),
  ('Bir şehirde bisiklet yolu yapılan caddelerde trafik kazalarının azaldığı bildiriliyor. Ancak belediye bisiklet yollarını zaten trafiği az ve geniş caddelere yapmış. Bu bilgi, bulgunun yorumunu nasıl etkiler?', 'Fark, caddelerin önceden farklı olmasından kaynaklanabilir.', ['Bisiklet yollarının kazaları kesin olarak azalttığını doğrular.', 'Bulgunun güvenirliğini artırır, çünkü geniş caddeler daha iyi ölçülür.', 'Kaza verisinin tamamen uydurma olduğunu kanıtlar.'], 'Uygulamanın yeri rastgele değil, sonuçla ilişkili özelliklere göre seçilmiştir. Bu seçim, müdahalenin etkisini karıştırıcı özelliklerden ayırmayı zorlaştırır.'),
  ('Bir okul müdürü, "Kütüphaneyi sık kullanan öğrencilerin notları daha yüksek" verisine dayanarak tüm öğrencilere kütüphanede zorunlu saat koymayı düşünüyor. Bu kararın dayanağındaki temel varsayım nedir?', 'Kütüphane kullanımının başarıyı artırdığı', ['Başarılı öğrencilerin kütüphaneye daha çok gittiği', 'Kütüphanenin her zaman kalabalık olduğu', 'Notların kütüphane kayıtlarından hesaplandığı'], 'Müdürün kararı nedenselliği varsayar. Oysa başarılı ve istekli öğrencilerin kütüphaneyi daha çok kullanması da aynı veriyi üretir; zorunlu saat bu isteği yaratmayabilir.'),
  ('Bir araştırma, evinde köpek olan çocuklarda alerji oranının daha düşük olduğunu buldu. Hangi bilgi, bu ilişkinin ters nedensellikten kaynaklanabileceğini düşündürür?', 'Alerjili ailelerin köpek beslemekten kaçınması', ['Köpeklerin çocukların bağışıklığını uyarması', 'Köpek sahiplerinin daha çok kırsalda yaşaması ve hayvanlarla temas etmesi', 'Alerji tanısının doktorlarca konması'], 'Aile alerji nedeniyle köpek almıyorsa, alerji köpek sahipliğini etkiliyor demektir. Bu durumda köpeğin koruyucu olduğu sonucu ters yönlü bir ilişkiye dayanabilir.'),
  ('Bir vaka-kontrol çalışmasında her hasta için aynı yaş ve cinsiyetten bir sağlıklı kontrol seçilmiştir. Bu uygulama hangi amaca hizmet eder?', 'Yaş ve cinsiyetin karıştırıcı etkisini azaltmak', ['Hatırlama yanlılığını ve ölçme hatasını tamamen ortadan kaldırmak', 'Örneklemi rastgele hâle getirmek', 'Ölçme aracının güvenirliğini artırmak'], 'Eşleştirme, seçilen değişkenler bakımından grupları benzer kılar. Ancak eşleştirilmeyen karıştırıcılar ve hatırlama yanlılığı sürebilir.'),
  ('Bir çalışmada kahve tüketimi ile kalp hastalığı ilişkisi sigara içenler ve içmeyenler olarak ayrı ayrı incelendiğinde her iki grupta da ilişki kayboluyor. Bu sonuç ne anlama gelir?', 'İlişki büyük olasılıkla sigaradan kaynaklanıyordu.', ['Kahve kalp hastalığını kesin olarak ve sigaradan bağımsız biçimde artırır.', 'Sigara bir aracı değişkendir.', 'İlişki her iki grupta da güçlenmiştir.'], 'Karıştırıcının her düzeyinde ilişkinin kaybolması, ham ilişkinin karıştırıcıdan kaynaklandığını gösterir. Tabakalama bu nedenle karıştırıcılığı ortaya çıkarmanın temel yoludur.'),
  ('Bir ülkenin GSYH\'si nominal olarak 20 yılda iki katına çıkmıştır; aynı dönemde fiyatlar da iki katına çıkmıştır. Reel büyüme hakkında ne söylenebilir?', 'Reel üretim yaklaşık aynı kalmıştır.', ['Reel üretim, fiyatlarla birlikte iki katına çıkmıştır.', 'Reel üretim dört katına çıkmıştır.', 'Reel üretim yarıya inmiştir.'], 'Nominal artışın tamamı fiyat artışından kaynaklanıyorsa reel üretimde artış yoktur. Zaman içinde parasal değerleri karşılaştırırken enflasyon düzeltmesi gerekir.'),
  ('Bir film şirketi, filminin "tüm zamanların en çok hasılat yapan filmi" olduğunu duyuruyor; ancak biletler eskiye göre çok daha pahalıdır. Daha adil bir karşılaştırma için ne yapılmalıdır?', 'Hasılatı enflasyona göre düzeltmek ya da bilet sayısına bakmak', ['Filmin süresini dakika olarak karşılaştırıp uzun filmleri öne çıkarmak', 'Yalnızca son bir yılın filmlerini karşılaştırmak', 'Hasılatı oyuncu sayısına bölmek'], 'Fiyatlar yükseldikçe nominal hasılat kendiliğinden artar. Enflasyona göre düzeltilmiş hasılat ya da satılan bilet sayısı farklı dönemleri daha adil karşılaştırır.'),
  ('Bir belediye, sokak lambalarını LED\'e çevirdikten sonraki yıl gece kazalarının %15 azaldığını açıklıyor. Aşağıdaki bilgilerden hangisi bu iddiayı en çok güçlendirir?', 'Lamba değişmeyen benzer ilçelerde kazaların değişmemesi', ['LED lambaların daha az elektrik harcaması', 'Kazaların çoğunun gündüz olması', 'Belediyenin lamba değişimini seçim öncesinde ve hızla tamamlamış olması'], 'Benzer ama uygulamanın yapılmadığı bölgelerde değişim olmaması, düşüşün genel eğilim ya da tesadüf olmadığını düşündürür. Bu, karşılaştırma grubunun gücüdür.'),
  ('Bir araştırma, yüksek lisans mezunlarının lisans mezunlarından daha fazla kazandığını gösteriyor. Hangi açıklama, yüksek lisansın kazancı artırdığı iddiasına bir rakip açıklama olarak en güçlüdür?', 'Yüksek lisans yapanların baştan daha yetenekli olması', ['Yüksek lisans programlarının iki yıl sürmesi', 'Lisans mezunlarının sayısının daha fazla olması ve maaşlarının yıllık hesaplanması', 'Maaşların yıllık olarak hesaplanması'], 'Kendini seçen bireyler, eğitimden bağımsız olarak daha yüksek kazanacak özelliklere sahip olabilir. Bu seçim etkisi, eğitimin nedensel getirisini abartabilir.'),
  ('Bir hükümet, asgari ücret artışından sonraki yıl işsizliğin düştüğünü belirterek artışın istihdamı artırdığını savunuyor. Bu çıkarımın temel zaafı nedir?', 'Aynı dönemdeki ekonomik canlanmanın göz ardı edilmesi', ['İşsizlik oranının yüzde olarak hesaplanması ve aylık açıklanması', 'Asgari ücretin aylık olarak belirlenmesi', 'Verinin resmî kurumdan alınması'], 'Önce-sonra karşılaştırması, aynı dönemde işsizliği etkileyen başka etkenleri dışlamaz. Benzer bölgelerle karşılaştırma ya da farkların farkı yöntemi gerekir.'),
  ('Bir otomobil reklamı, "Bu modelin sahiplerinin %95\'i 10 yıl sonra hâlâ aynı arabayı kullanıyor" diyor. Bu istatistik araç dayanıklılığı hakkında neden sınırlı bilgi verir?', 'Arabası bozulup satanlar artık sahip sayılmamaktadır.', ['%95 oranı çok düşüktür.', 'Arabalar 10 yıl dayanamaz.', 'Sahiplerin yaşı ve hangi şehirde oturdukları bilinmemektedir.'], 'Hâlâ arabayı kullananlara bakmak, sorun yaşayıp arabadan kurtulanları dışarıda bırakabilir. Bu, hayatta kalan yanlılığına benzer bir seçici kaynak sorunudur.'),
  ('Bir sağlık bakanlığı, yeni bir aşının yan etki bildirim sisteminde yüzlerce baş ağrısı raporu olduğunu açıklıyor. Bu raporların aşının baş ağrısına yol açtığını kanıtlamamasının nedeni nedir?', 'Baş ağrısı zaten sıktır; beklenen sıklıkla karşılaştırma yapılmamıştır.', ['Bildirim sistemlerine hiç rapor gelmez.', 'Baş ağrısı tıbbi bir belirti değildir.', 'Aşının yan etkisi olamaz.'], 'Kendiliğinden bildirim sistemleri sinyal üretir ama sıklık karşılaştırması yapmaz. Aşı olanlarda ve olmayanlarda baş ağrısının oranı karşılaştırılmadıkça nedensellik çıkarılamaz.'),
  ('Bir araştırmacı, mahkûmların çocukluk travması oranının genel nüfustan yüksek olduğunu bulmuş ve "travma suça yol açar" sonucuna varmıştır. Bu sonucu zayıflatan bir seçim sorunu hangisidir?', 'Mahkûm olma olasılığının da sosyoekonomik etkenlere bağlı olması', ['Mahkûmların sayısının çok fazla olması', 'Travmanın tanımının açık olması', 'Çalışmanın cezaevinde yapılması nedeniyle güvenirliğin artması'], 'Mahkûm örneklemi suç işleyen herkesi değil, yakalanıp hüküm giyenleri temsil eder. Bu süreç yoksulluk gibi travmayla da ilişkili etkenlere bağlıysa sahte bir ilişki görülebilir.'),
  ('İki farklı yılın anket sonuçları karşılaştırılırken bir yıl sorunun "Hükümetin ekonomi politikasını destekliyor musunuz?", diğer yıl "Hükümetin başarılı ekonomi politikasını destekliyor musunuz?" biçiminde sorulduğu fark ediliyor. Bu karşılaştırmanın sorunu nedir?', 'Ölçme aracı değiştiği için fark gerçek değişimi yansıtmayabilir.', ['İki yıl arasında hiç görüş değişimi olmamıştır, çünkü sorular aynı konudadır.', 'İkinci soru daha yansızdır.', 'Anketler yıllar arasında karşılaştırılamaz.'], 'Soru ifadesindeki değişiklik yanıtları yönlendirebilir. İki ölçüm arasında araç değiştiğinde zaman içindeki eğilim yorumlanamaz.'),
  ('Bir ülkede yeni bir tanı kılavuzunun yayımlanmasının ardından otizm tanısı alan çocuk sayısı belirgin biçimde artmıştır. Bu artışı yorumlarken en önemli soru hangisidir?', 'Artışın ne kadarının ölçüt genişlemesinden geldiği', ['Kılavuzun kaç sayfa olduğu', 'Tanı koyan doktorların yaş ortalaması ve uzmanlık alanları', 'Kılavuzun hangi dilde yazıldığı'], 'Tanı ölçütleri ve farkındalık değiştiğinde, gerçek sıklık değişmese bile tanı sayısı artabilir. Ölçüm değişikliği ile gerçek değişim ayrılmalıdır.'),
  ('Bir yöneticinin, satışların en çok düştüğü ay ekibe motivasyon semineri verdirip ertesi ay satışların toparlandığını görmesi ve semineri başarılı sayması hangi iki kavramla açıklanabilir?', 'Ortalamaya dönüş ve kontrol grubunun yokluğu', ['Tavan etkisi ve taban oranı', 'Ekolojik yanılgı ve Simpson paradoksu', 'Hatırlama yanlılığı ile yayın yanlılığının birlikte görülmesi'], 'Olağandışı kötü bir ayın ardından satışlar kendiliğinden normale dönebilir. Seminer almayan bir karşılaştırma ekibi olmadan bu iki etki ayrılamaz.'),
  ('Bir ölçeğin maddeleri ikiye bölünüp (örneğin tek ve çift numaralı maddeler) iki yarının puanları arasındaki korelasyonun hesaplanmasına ne denir?', 'İki yarı güvenirliği', ['Test-tekrar test güvenirliği', 'Yordama geçerliliği', 'Puanlayıcılar arası uyum katsayısı'], 'İki yarı yöntemi, tek uygulamayla iç tutarlılığı kestirir. Yarım testin güvenirliği tam testten düşük olacağından Spearman-Brown düzeltmesi uygulanır.'),
  ('Bir öğrenci aynı zekâ testini iki kez alıyor; ilkinde çok yorgun ve uykusuz, ikincisinde dinlenmiş durumda. İki puan arasındaki farkın kaynağı ölçme kuramında nasıl sınıflandırılır?', 'Geçici kişisel durumlardan doğan rastlantısal hata', ['Testin yapısından doğan sistematik geçerlilik hatası', 'Örnekleme hatası', 'Testin kapsam geçerliliğindeki eksiklik'], 'Yorgunluk, dikkat ve ruh hâli gibi geçici durumlar ölçümden ölçüme değişen rastlantısal hata kaynaklarıdır ve güvenirliği düşürür.'),
  ('Bir öğretmen, kompozisyonları puanlarken kâğıtların okunaklı yazılmış olanlarına içerikten bağımsız olarak daha yüksek puan veriyor. Bu durum hangi kavramla ilgilidir?', 'Hale etkisi', ['Tavan etkisi', 'Plasebo etkisi', 'Ortalamaya dönüş'], 'Hale etkisi, bir özelliğe ilişkin olumlu izlenimin başka özelliklerin değerlendirmesini etkilemesidir. Bu, puanlamanın geçerliliğini düşürür; isimsiz ve rubrikli puanlama yardımcı olur.'),
  ('Bir zekâ testinin belirli bir kültürel gruba özgü kelime ve deneyimler içermesi, diğer gruplardan gelen öğrencilerin puanlarını düşürüyor. Bu durum hangi sorunu gösterir?', 'Ölçme yanlılığı', ['Örneklemin çok büyük olması', 'Yüksek iç tutarlılık', 'Rastgele atama hatası'], 'Puanlar ölçülmek istenen yetenek yerine kültürel aşinalığı da yansıttığında test bazı gruplar için yanlıdır. Bu, yapı geçerliliğinin gruplar arasında bozulmasıdır.'),
  ('Bir hastanın ağrısını 0–10 arası sayısal ölçekle değerlendirmesi istendiğinde, bir hastanın "7"si başka bir hastanın "7"siyle aynı ağrıyı ifade etmeyebilir. Bu durum ağrı ölçümünün hangi özelliğini gösterir?', 'Kişiler arası karşılaştırmanın öznelliği', ['Ölçeğin kusursuz nesnelliği', 'Ölçeğin oran ölçeği olması', 'Ağrının hiç ölçülememesi'], 'Öznel ölçekler kişinin kendi referans noktasına dayanır. Bu ölçümler aynı kişide zaman içindeki değişimi izlemek için daha güvenilirdir.'),
  ('Bir okulda öğrencilerin "okul bağlılığı" anketi ile devamsızlık kayıtları arasında güçlü negatif ilişki bulunuyor. Bu bulgu anket için hangi geçerlilik kanıtını sağlar?', 'Ölçüt geçerliliği', ['Görünüş geçerliliği', 'İç tutarlılık', 'Paralel formlar güvenirliği'], 'Kurama göre bağlılığı yüksek öğrencilerin devamsızlığı az olmalıdır. Anket puanlarının bu dış ölçütle beklenen yönde ilişkili olması ölçüt geçerliliğini destekler.'),
  ('Bir iş başvurusu testinin geçerliliğini değerlendirmek için yalnızca işe alınanların sonraki performansına bakmanın sorunu nedir?', 'İşe alınmayanların performansı bilinmediğinden aralık kısıtlanır.', ['İşe alınanların performansı ölçülemez.', 'Test puanları her zaman yüksek çıkar.', 'Yalnızca işe alınmayanlar test edildiği için puanlar karşılaştırılamaz.'], 'Düşük puanlılar işe alınmadığından veri yalnızca yüksek puanlıları içerir. Aralık kısıtlaması, testin gerçek yordama gücünü olduğundan düşük gösterir.'),
  ('Bir sınavda herkesin doğru yanıtladığı bir maddenin ölçme açısından değeri nedir?', 'Öğrencileri ayırt etmediği için bilgi değeri düşüktür.', ['Sınavın en ayırt edici maddesidir.', 'Sınavın geçerliliğini kesin olarak artırır ve güvenirliği yükseltir.', 'Ölçme hatasını sıfıra indirir.'], 'Madde ayırıcılığı, yüksek ve düşük başarılıları ayırma gücüdür. Herkesin doğru ya da herkesin yanlış yanıtladığı maddeler bu açıdan işe yaramaz.'),
  ('Bir okul, en düşük başarılı 10 sınıfa ek öğretmen verip sonraki yıl bu sınıfların başarısının arttığını raporluyor. Aynı yıl ek öğretmen almayan en düşük başarılı başka 10 sınıfın da başarısı arttı. Bu bilgi neyi gösterir?', 'Artışın bir kısmı ortalamaya dönüşten kaynaklanabilir.', ['Ek öğretmenin etkisi kesin olarak iki katına çıkmıştır.', 'Ek öğretmenin başarıyı düşürdüğü kanıtlanmıştır.', 'Başarı ölçümü tamamen geçersizdir.'], 'Aynı ölçütle seçilen ve müdahale almayan sınıflarda da artış olması, düşük başlangıç düzeyinin kendiliğinden düzeleceğini gösterir. Gerçek etki iki grubun artışları arasındaki farktır.'),
  ('Bir ülke haritasında illeri toplam hasta sayısına göre koyu renkle boyamak hangi yanılgıya yol açabilir?', 'Kalabalık iller, oranları düşük olsa da riskli görünür.', ['Küçük iller her zaman en riskli görünür.', 'Renkler hasta sayısını gösteremez.', 'Haritalar oranları kendiliğinden düzelttiği için hiçbir yanılgı oluşmaz.'], 'Toplam sayılar nüfusla büyür; bu tür haritalar çoğu zaman nüfus haritasına benzer. Karşılaştırma için kişi başına oranlar gösterilmelidir.'),
  ('Bir ekonomi haberinde, bir göstergenin 2020 yılı çok düşük olduğu için 2021\'de "%30 büyüdüğü" vurgulanıyor. Bu artışı yorumlarken dikkat edilmesi gereken etki nedir?', 'Düşük başlangıçtan doğan baz etkisi', ['Mevsimsellik etkisi ve tavan etkisi', 'Hawthorne etkisi', 'Plasebo etkisi'], 'Olağandışı düşük bir yıldan sonraki büyüme oranı, toparlanmanın gerçekte olduğundan güçlü görünmesine yol açar. Uzun dönemli düzeyle karşılaştırmak gerekir.'),
  ('Bir araştırmada 1.000 test yapılmış ve sıfır hipotezlerinin hepsinin doğru olduğu varsayılmıştır. 0,05 anlamlılık düzeyinde yaklaşık kaç yanlış pozitif sonuç beklenir?', '50', ['5', '500', '0'], 'Her testte %5 yanlış pozitif olasılığı varsa 1.000 testte yaklaşık 1.000 × 0,05 = 50 yanlış pozitif beklenir.'),
  ('Aynı sorunun iki ayrı çalışmasında biri p = 0,01, diğeri p = 0,20 bulmuştur. Bu iki sonucun birbiriyle "çeliştiği" yorumu neden aceleci olabilir?', 'Etki büyüklükleri benzer, örneklemler farklı olabilir.', ['p-değerleri farklı olduğuna göre etkiler kesinlikle zıt yöndedir.', 'İkinci çalışma kesin olarak hatalıdır.', 'p-değerleri hiçbir zaman karşılaştırılamaz.'], 'Anlamlı ve anlamsız sonuçlar arasındaki fark kendisi anlamlı olmayabilir. Etki kestirimleri ve güven aralıkları birlikte incelenmelidir.'),
  ('Bir araştırmacının "p = 0,06; sonuç anlamlılığa yaklaştı" ifadesiyle ilgili en dengeli görüş hangisidir?', 'Sonucu zayıf ve belirsiz bir kanıt saymak', ['Sonucu kesinlikle anlamlı saymak', 'Sonucu etkinin kesinlikle hiç olmadığının kanıtı saymak', 'p-değerini 0,05\'e yuvarlamak'], 'p = 0,06 ile 0,04 arasında kanıt gücü bakımından büyük bir fark yoktur. Ancak sonuç ne kesin bir bulgu ne de etkinin yokluğunun kanıtıdır.'),
  ('"Olağanüstü iddialar olağanüstü kanıt gerektirir" ilkesi hangi akıl yürütmeyle en iyi açıklanır?', 'Önsel olasılığı düşük iddiaların ancak güçlü kanıtla inandırıcı olması', ['Her iddianın aynı miktarda kanıtla kabul edilmesi', 'Kanıtın hiçbir zaman inancı değiştirmemesi', 'Olağanüstü iddiaların kanıtsız kabul edilmesi'], 'Bilinen bilgiyle çelişen bir iddianın doğru olma olasılığı başlangıçta düşüktür. Bu nedenle tek bir zayıf çalışma onu inandırıcı kılmaya yetmez; Carl Sagan bu ilkeyi yaygınlaştırmıştır.'),
  ('Bir çalışma, düzenli diş ipi kullananların daha uzun yaşadığını bulmuştur. Bu ilişkinin büyük kısmını açıklayabilecek olası karıştırıcı hangisidir?', 'Diş ipi kullananların sağlığına daha çok önem vermesi', ['Diş ipinin kana karışarak bağışıklığı güçlendirmesi ve ömrü uzatması', 'Diş ipinin ucuz olması', 'Diş hekimlerinin diş ipi önermesi'], 'Diş ipi kullanmak sağlığa dikkat eden bir yaşam tarzının göstergesi olabilir. Bu "sağlıklı kullanıcı" etkisi pek çok sağlık davranışı araştırmasını karıştırır.'),
  ('Bir kişinin, aslında ilişkisiz iki olayı (örneğin dolunay ile acil servis yoğunluğu) birbiriyle ilişkili sanması ve akılda kalan çakışmaları hatırlaması hangi kavramla adlandırılır?', 'Yanıltıcı korelasyon', ['Ters nedensellik', 'Ekolojik yanılgı', 'Tavan etkisi'], 'Yanıltıcı (illüzyonel) korelasyonda dikkat çekici eşleşmeler hatırlanır, eşleşmeyen durumlar unutulur. Sistematik kayıtlar dolunayla acil yoğunluğu arasında tutarlı bir ilişki göstermemiştir.'),
  ('Bir kişinin, ulaşmak istediği sonuca uygun kanıtları kolayca kabul edip istemediği sonuca işaret eden kanıtlara çok daha yüksek ölçüt uygulaması hangi kavramla açıklanır?', 'Güdülenmiş akıl yürütme', ['Ortalamaya dönüş', 'Taban oranı yanılgısı', 'Yenilik etkisi'], 'Güdülenmiş akıl yürütmede değerlendirme ölçütleri istenen sonuca göre değişir. Bu, doğrulama yanlılığıyla yakından ilişkilidir.'),
  ('Bir araştırmacının kayıp anahtarlarını yalnızca ışığın olduğu yerde araması benzetmesiyle anlatılan "sokak lambası etkisi" araştırmada neyi ifade eder?', 'Ölçmesi kolay yerde aramak, doğru yerde değil', ['Yalnızca gece yapılan araştırmaların geçersiz sayılması gerektiği', 'Sokak aydınlatmasının suçu azaltması', 'Işık yoğunluğunun ölçme hatası yaratması'], 'Araştırmacılar veri kolay bulunduğu için yanıtın bulunması en olası olmayan yerlere odaklanabilir. Bu, yanlış soruyla doğru veriyi analiz etmeye yol açar.'),
  ('Tıpta bir ilacın asıl hedef olan ölüm ya da kalp krizi yerine kolesterol düzeyi gibi bir laboratuvar değerini düşürüp düşürmediğine bakılmasına ne ad verilir?', 'Vekil sonlanım kullanımı', ['Tedavi niyeti (intention-to-treat) analizi', 'Çift kör düzen', 'Yayın yanlılığı'], 'Vekil sonlanımlar ölçmesi daha kolay ve hızlıdır, ancak hastalar için önemli sonuçlarla her zaman paralel gitmeyebilir.'),
  ('Bir şirket "mutlu çalışan" oranını ölçmek için yalnızca çalışanların işe geç kalma sıklığına bakıyor. Bu durumda geç kalma hangi rolü oynar ve bu yaklaşımın riski nedir?', 'Dolaylı gösterge; mutluluğu tam yansıtmayabilir.', ['Doğrudan ölçüm; hiçbir risk taşımaz.', 'Karıştırıcı değişken; geç kalmayla mutluluk arasındaki nedenselliği kanıtlar.', 'Rastgele atama; grupları dengeler.'], 'Ulaşım ya da aile sorumlulukları gibi pek çok etken geç kalmayı etkiler. Dolaylı (vekil) bir gösterge, asıl yapıyla zayıf ilişkiliyse yanıltıcı sonuçlar verir.'),
  ('Bir haber, birkaç ayrı olayı ardışık bir hikâye gibi bağlayıp aralarında neden-sonuç ilişkisi kuruyor; ancak bu bağlantılar veriye dayanmıyor. Bu eğilime ne ad verilir?', 'Anlatı yanılgısı', ['Doz-yanıt ilişkisi', 'Tedavi niyeti', 'Paralel formlar'], 'İnsanlar olayları anlamlı bir hikâyeye dönüştürmeye yatkındır. Tutarlı bir anlatı inandırıcı görünse de nedensellik kanıtı yerine geçmez.'),
  ('Birbirinden bağımsız 10.000 kişinin her yıl %50 olasılıkla başarılı olduğu bir durumda, beş yıl üst üste başarılı olması beklenen kişi sayısı yaklaşık kaçtır?', '313', ['2.000', '50', '1.250'], 'Beş yıl üst üste başarı olasılığı (1/2)⁵ = 1/32\'dir. 10.000 / 32 ≈ 313 kişi beklenir.'),
  ('Bir ilacın etkililiği için yayımlanmış ve yayımlanmamış tüm deneyleri içeren bir derlemenin, yalnızca yayımlanmış deneylere dayanan derlemeden daha küçük bir etki bulması en çok neyi gösterir?', 'Yayımlanmamış deneylerin daha olumsuz sonuçlar içerdiğini', ['Yayımlanmamış deneylerin daha büyük örneklemli ve daha güvenilir olduğunu', 'Yayımlanmış deneylerin tümünün sahte olduğunu', 'Etki büyüklüğünün hesaplanamadığını'], '2008\'de antidepresanlarla ilgili bir analiz, ABD ilaç dairesine sunulan olumsuz sonuçlu deneylerin çoğunun yayımlanmadığını ve yayımlanmış literatürün etkiyi abarttığını gösterdi.'),
  ('Bir derginin yalnızca "yeni ve şaşırtıcı" bulguları yayımlayıp tekrar çalışmalarını reddetmesi, bilimsel literatürde uzun vadede ne yaratır?', 'Doğrulanmamış bulguların birikmesine', ['Bulguların tamamının kesin olarak doğrulanmasına', 'Yanlış pozitiflerin tamamen kaybolmasına', 'Meta-analizlerin gereksiz hâle gelmesine'], 'Tekrarlar yayımlanmadığında hatalı bulgular düzeltilmeden kalır. Bu teşvik yapısı tekrarlanabilirlik krizinin nedenlerinden biri olarak gösterilmiştir.'),
  ('1987\'de New York\'ta veteriner kliniğine getirilen kedilerle ilgili bir çalışmada, yedinci kattan daha yüksekten düşen kedilerin daha alçaktan düşenlere göre daha az yaralandığı bildirilmiştir. Bu bulguya yöneltilen en önemli yöntemsel eleştiri nedir?', 'Yüksekten düşüp ölen kedilerin kliniğe getirilmemesi', ['Kedilerin kat sayısını hatırlayamaması', 'Klinikteki veterinerlerin kedileri tanımaması', 'Kedilerin hiç yaralanmamış olması'], 'Ölen kediler veriye girmediyse, yüksekten düşüp kliniğe ulaşanlar zaten şanslı olanlardır. Bu durum hayatta kalan yanlılığına bağlı bir seçim sorunudur.'),
  ('Bir ilacın sıkı denetimli bir deneyde gösterdiği etki ile günlük klinik uygulamada gösterdiği etki arasındaki fark, hangi kavram çiftiyle açıklanır?', 'Etkinlik ve etkililik', ['Güvenirlik ve geçerlilik', 'Duyarlılık ve özgüllük', 'Tip I ve Tip II hata'], 'Etkinlik ideal koşullardaki yararı, etkililik ise gerçek yaşamdaki yararı ifade eder. İlacı düzenli kullanmama, ek hastalıklar ve farklı hasta grupları etkiyi değiştirebilir.'),
  ('Bir okuma programı, deneyimli ve gönüllü öğretmenlerle yürütülen pilot okullarda başarılı olmuş; ülke geneline yayıldığında etkisi belirgin biçimde azalmıştır. Bunun en olası açıklaması nedir?', 'Uygulama koşullarının ve uygulayıcıların farklı olması', ['Programın pilotta hiç uygulanmamış olması', 'Ülke genelinde öğrencilerin okumayı hiç bilmemesi ve programı anlamaması', 'Etkinin örneklem büyüdükçe artması'], 'Ölçeklendirme sırasında eğitim, kaynak ve gönüllülük gibi koşullar değişir. Pilot sonuçlarının geniş uygulamaya aktarılması dış geçerlilik sorunudur.'),
  ('Bir test, aynı türden maddeler eklenerek iki katı uzunluğa getirilirse güvenirliği genellikle nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfıra iner.'], 'Daha çok madde, rastlantısal hataların birbirini dengelemesine olanak verir. Spearman-Brown formülü bu artışı kestirir; ancak maddeler yapıyla ilgili olmalıdır.'),
  ('Bir ağrı ilacının ağrıyı 10\'luk ölçekte ortalama 0,3 puan azalttığı ve bunun anlamlı bulunduğu bildiriliyor. Hastalar için anlamlı bir değişim için genellikle yaklaşık 1–2 puanlık bir eşik kabul ediliyor. Bu bilgi sonucu nasıl yorumlatır?', 'Etki anlamlı olsa da klinik olarak önemsiz olabilir.', ['Etki hastalar için kesin olarak çok büyüktür.', 'Sonuç anlamlı olmadığı için hesaplama hatalıdır.', 'Ölçek ağrıyı ölçmek için uygun değildir.'], 'Klinik olarak anlamlı en küçük fark, hastanın fark edeceği değişimi ifade eder. Bunun altında kalan farklar istatistiksel olarak anlamlı olsa bile pratik değeri sınırlıdır.'),
  ('Bir kişi, aynı gün iki farklı arkadaşına rastladığı için bunun olağanüstü bir tesadüf olduğunu düşünüyor. İstatistiksel açıdan bu durumun değerlendirilmesinde hangi ilke önemlidir?', 'Çok sayıda olası olayda bazı çakışmalar kaçınılmazdır.', ['Her tesadüf mutlaka gizli bir nedene işaret eder.', 'Tesadüflerin olasılığı her zaman sıfırdır.', 'İki olay asla aynı gün gerçekleşmez.'], 'Bir yıl boyunca karşılaşılabilecek kişi ve olay sayısı çok büyüktür. Belirli bir çakışma olasılıksız görünse de "herhangi bir" çakışma olasılığı yüksektir; bu, büyük sayılar ilkesidir.'),
  ('Émile Durkheim\'ın 19. yüzyılda Protestan nüfusu fazla olan bölgelerde intihar oranlarının daha yüksek olduğunu bulması, bireysel düzeyde nasıl bir uyarıyı gerektirir?', 'Bölge verisi, intihar edenlerin Protestan olduğunu göstermez.', ['Bölge verisi bireyler için kesin kanıt sağlar.', 'İntihar oranları bölgesel olarak ölçülemez, yalnızca ulusal düzeyde hesaplanır.', 'Din bilimsel olarak incelenemez.'], 'Bölge düzeyinde bir ilişkiden bireylerin özelliklerine dair çıkarım yapmak ekolojik yanılgı riski taşır. Bireysel düzeydeki veriler aynı ilişkiyi göstermeyebilir.'),
  ('Bir şehirde zengin mahallelerde oy verme oranı yüksektir; bir araştırmacı bundan "zengin kişiler daha çok oy verir" sonucuna varıyor. Bu çıkarımı doğrudan sınamanın en iyi yolu hangisidir?', 'Bireylerin gelirini ve oy davranışını kişi düzeyinde incelemek', ['Daha çok mahallenin ortalamasını alıp mahalle sayısını iki katına çıkarmak', 'Mahallelerin adlarını değiştirmek', 'Oy sayımını tekrarlamak'], 'Bireysel düzeydeki bir iddia ancak bireysel veriyle doğrudan sınanabilir. Mahalle ortalamaları ne kadar çok olursa olsun ekolojik yanılgı riskini gidermez.'),
  ('Bir sınıfta 40 öğrenciden 30\'u ders çalışma uygulaması kullanıyor. Kullananların 18\'i, kullanmayanların 6\'sı sınavı geçmiştir. Geçme oranları için hangi karşılaştırma doğrudur?', 'Kullananlarda %60, kullanmayanlarda %60', ['Kullananlarda %60, kullanmayanlarda %20', 'Kullananlarda %45, kullanmayanlarda %15', 'Kullananlarda %75, kullanmayanlarda %25'], 'Kullananlarda 18/30 = %60, kullanmayanlarda 6/10 = %60\'tır. Ham sayılar (18\'e karşı 6) farklı görünse de oranlar eşittir; uygulamayla geçme arasında ilişki yoktur.'),
  ('İki ilaç denemesinde A ilacı 50 hastanın 40\'ını, B ilacı 400 hastanın 300\'ünü iyileştirmiştir. Hangi yorum en doğrudur?', 'A\'nın oranı yüksek ama küçük örneklemde kestirim belirsizdir.', ['B daha çok hastayı iyileştirdiği için kesinlikle daha etkilidir.', 'İki ilacın oranı eşittir.', 'A\'nın oranı daha düşüktür.'], 'A: %80, B: %75\'tir. A\'nın oranı yüksek olsa da 50 hastalık örneklemin güven aralığı geniştir; ayrıca iki deney farklı hasta gruplarında yapılmış olabilir.'),
  ('Bir şirkette çalışanların %20\'si kadın, yöneticilerin %10\'u kadındır. Bu iki oran hangi soruyu yanıtlamaya yetmez?', 'Kadın ve erkeklerin terfi sürecinde eşit davranış görüp görmediğini', ['Yöneticiler arasında kadınların payının çalışanlardaki paydan düşük olduğunu', 'Çalışanların beşte birinin kadın olduğunu', 'Yöneticilerin onda birinin kadın olduğunu'], 'Oranlardaki fark kıdem, alan ve başvuru gibi pek çok etkenden kaynaklanabilir. Ayrımcılığı değerlendirmek için benzer nitelikli adayların terfi olasılıklarını karşılaştırmak gerekir.'),
  ('Bir köprüden günde ortalama 10.000 araç geçtiği, standart sapmanın ise 3.000 olduğu biliniyor. Belirli bir gün 11.000 araç geçmesi için en uygun değerlendirme hangisidir?', 'Olağan dalgalanma sınırları içindedir.', ['Olağanüstü bir artıştır ve mutlaka bir nedeni vardır.', 'Ölçüm hatası olduğu kesindir.', 'Ortalamanın yanlış hesaplandığını gösterir.'], '11.000 araç ortalamanın yalnızca yaklaşık üçte bir standart sapma üstündedir (z ≈ 0,33). Bu kadar küçük sapmalar sıradandır ve özel açıklama gerektirmez.'),
  ('İşsizlik verilerinde "mevsimsellikten arındırılmış" ifadesi ne anlama gelir?', 'Her yıl aynı dönemde yinelenen dalgalanmaların çıkarıldığı', ['Yalnızca yaz aylarının verilerinin kullanıldığı', 'Tarım çalışanlarının veriden tamamen çıkarıldığı', 'Verilerin bir yıl geriden yayımlandığı'], 'Örneğin turizm ve tarımdaki mevsimlik istihdam her yıl benzer dalgalanmalar yaratır. Bu dalgalanmalar çıkarıldığında aydan aya karşılaştırma daha anlamlı olur.'),
  ('Bir web sitesinin ziyaretçi sayısının her ay bir önceki aydan %10 fazla olduğu gözlenmiştir. Bu eğilimin hiç değişmeden 10 yıl süreceğini varsaymak neden sorunludur?', 'Üstel büyüme sınırsız süremez; doyma eğilimi değiştirir.', ['%10 büyüme matematiksel olarak hesaplanamaz.', 'Ziyaretçi sayıları her zaman azalır.', 'Aylık veriler yıllık tahmin için hiç kullanılamaz.'], 'Ayda %10 büyüme 10 yılda 1,1¹²⁰ ≈ 92.000 kattan fazla artış demektir. Gerçek dünyada pazar doygunluğu ve rekabet bu tür eğilimleri sınırlar.'),
  ('Bir okuldaki ortalama sınav puanı yıllar içinde artmış, ancak aynı dönemde sınavın zorluk düzeyinin düşürüldüğü anlaşılmıştır. Bu durumda puan artışının yorumu nasıl yapılmalıdır?', 'Artış ölçme aracının değişimini yansıtabilir.', ['Artış başarının kesin olarak arttığını gösterir.', 'Sınav zorluğu puanları etkilemez.', 'Puanlar ancak düşerse bir şey ifade eder.'], 'Ölçme aracının değişmesi, gerçek değişimle karıştırılabilir. Zaman içinde karşılaştırma için eşitlenmiş ya da aynı güçlükteki sınavlar gerekir.'),
  ('Bir sporcu antrenmanına yeni bir takviye ekledikten sonra koşu derecesinin iyileştiğini görüyor; aynı dönemde antrenman yükünü de artırmış. Takviyenin etkisini değerlendirmek için bu sporcunun en uygun yaklaşımı hangisi olurdu?', 'Diğer koşulları sabit tutup plaseboyla, kör ve dönüşümlü denemek', ['Takviyeyi ve antrenman yükünü aynı anda artırmaya devam etmek', 'Yalnızca en iyi derecesini kaydedip diğerlerini silmek', 'Takviyenin etiketindeki iddiaları okumak'], 'Aynı anda iki değişiklik yapıldığında etkiler ayrılamaz. Tek kişilik dönüşümlü (n-of-1) körlü denemeler kişisel düzeyde daha güvenilir bilgi verir.'),
  ('Bir şehirde trafik kazası ölümleri azalırken kazalarda yaralanan sayısı artmıştır. Bu verilerden çıkarılabilecek en temkinli sonuç hangisidir?', 'Kazaların ağırlığı azalmış, ölümcül kazalar yaralanmalıya dönmüş olabilir.', ['Trafik güvenliği kesin olarak kötüleşmiştir.', 'Kaza sayısı değişmemiştir.', 'Ölüm kayıtları kesin olarak hatalıdır.'], 'Daha iyi araç güvenliği ya da acil müdahale, ölebilecek kişilerin yaralı olarak kurtulmasını sağlayabilir. Tek bir göstergeye bakmak yanıltıcı olabilir.'),
  ('Bir ülkenin ortalama yaşam süresi 1900\'de yaklaşık 45 yıldı. Bu bilgi, o dönemde insanların çoğunun 45 yaş civarında öldüğü anlamına gelir mi?', 'Hayır; yüksek bebek ölümleri ortalamayı aşağı çekiyordu.', ['Evet; herkes 45 yaşında ölürdü.', 'Evet; yaşlı insan yoktu.', 'Hayır; ortalama yaşam süresi o dönemde hesaplanamazdı.'], 'Doğumda beklenen yaşam süresi bebek ve çocuk ölümlerinden çok etkilenir. Çocukluğu atlatan pek çok kişi 60–70 yaşlarına kadar yaşayabiliyordu.'),
  ('Bir araştırmada 1960\'lı yıllarda doğanların 1990\'da doğanlara göre aynı yaşta daha az teknoloji kullandığı bulunmuştur. Bu farkın yaşlanmadan değil doğum dönemi farkından kaynaklanması hangi kavramla açıklanır?', 'Kuşak (kohort) etkisi', ['Olgunlaşma etkisi', 'Hawthorne etkisi', 'Plasebo etkisi'], 'Kuşak etkisi, aynı dönemde doğanların ortak deneyimlerinden kaynaklanan farklardır. Kesitsel karşılaştırmalarda yaş etkisi ile kuşak etkisi kolayca karışır.'),
  ('Bir tartışmada taraflardan biri kendi görüşünü destekleyen 3 çalışmayı gösterirken aynı konuda yapılmış ve aksini bulan 30 çalışmayı anmıyor. Bu kanıt kullanımını değerlendirmenin en iyi yolu nedir?', 'Konudaki tüm çalışmaları sistematik biçimde gözden geçirmek', ['Daha çok çalışma gösteren tarafı otomatik olarak haklı saymak', 'Yalnızca en yeni çalışmaya bakıp gerisini göz ardı etmek', 'Çalışmaların yazarlarının ünlü olup olmadığına bakmak'], 'Seçici kanıt kullanımı, kanıtın bütününü çarpıtır. Sistematik derleme, seçim yanlılığını azaltarak tüm bulguları değerlendirir.'),
  ('Bir ülkede askerlik yükümlülüğünün doğum tarihine göre yapılan bir kurayla belirlenmesi, askerliğin sonraki gelire etkisini incelemek için neden değerli bir fırsattır?', 'Kura, askerlik yapıp yapmamayı kişisel özelliklerden bağımsız belirler.', ['Kura sonucunda askerlik yapanların tamamı zengin olur.', 'Kura, katılımcıların gelirini önceden eşitler ve sabitler.', 'Kura nedeniyle hiç kimse askerlik yapmaz.'], 'Doğum tarihine bağlı kura doğal bir rastgele atama sağlar. Vietnam savaşı dönemi ABD kurası bu amaçla incelenen bilinen bir doğal deneydir.'),
  ('İkizler üzerinde yapılan çalışmalar, bir özelliğin genetik ve çevresel etkilerini ayırmakta neden yararlıdır?', 'Tek yumurta ikizleri genetik olarak özdeş olduğundan çevre farkının etkisi gözlenebilir.', ['İkizlerin hiçbir ortak çevresel deneyimi olmadığı için çevre etkisi sıfırdır.', 'İkizler her zaman farklı ülkelerde büyür.', 'İkizlerde ölçme hatası olmaz.'], 'Genetik benzerlik derecesi bilinen ikiz çiftlerini karşılaştırmak, genetik ve çevresel katkıları kestirmeye yardım eder. Bu da doğanın sağladığı bir karşılaştırma düzenidir.'),
  ('Bir ankette katılımcılara "Geçen ay kaç kez fast food yediniz?" diye soruluyor. Yanıtların gerçek sayıdan sistematik olarak sapmasına yol açabilecek iki etken hangisidir?', 'Hatırlama güçlüğü ve sosyal beğenirlik', ['Rastgele atama ve tabakalama yöntemlerinin birlikte kullanılması', 'Simpson paradoksu ve ekolojik yanılgı', 'Tavan etkisi ve taban etkisi'], 'Bir ay öncesini doğru hatırlamak zordur ve sağlıksız beslenmeyi olduğundan az bildirme eğilimi vardır. İkisi birlikte sistematik sapma yaratabilir.'),
  ('Bir laboratuvar fare deneyinde tüm fareler aynı soydan, aynı yaşta ve aynı koşullarda tutulmaktadır. Bu düzenin iç geçerliliğe katkısı ve dış geçerliliğe bedeli nedir?', 'Karıştırıcıları azaltır; ama sonuçların genellenmesini sınırlar.', ['Karıştırıcıları artırır; ama genellenebilirliği kesin olarak garanti eder.', 'İç ve dış geçerliliği aynı anda ve kesin olarak en üst düzeye çıkarır.', 'Geçerlilik üzerinde hiçbir etkisi yoktur.'], 'Tek tip denekler gruplar arası farkı müdahaleye bağlamayı kolaylaştırır. Ancak farklı soy, yaş ve koşullarda sonuç değişebilir.'),
  ('Aynı konuyu inceleyen beş küçük çalışmanın her biri tek başına anlamlı sonuç bulamamıştır, ancak hepsi aynı yönde küçük bir etki göstermiştir. Bu çalışmalar birleştirildiğinde ne olabilir?', 'Birleşik analiz anlamlı bir etki ortaya koyabilir.', ['Birleşik analiz her zaman ve kaçınılmaz olarak sıfır etki bulur.', 'Birleştirme yapmak bilimsel olarak yasaktır.', 'Etki büyüklüğü beş katına çıkar.'], 'Meta-analiz örneklemleri birleştirerek gücü artırır. Tek tek yetersiz güçlü çalışmalar birlikte tutarlı bir etkiyi gösterebilir.'),
  ('Bir sporcunun "Bu sezon formsuz olduğum için kötü oynadım" açıklaması ile "Kötü oynadığım için formsuz göründüm" ifadesi arasındaki fark hangi kavramla ilgilidir?', 'Nedensellik yönü', ['Ölçümün güvenirlik katsayısı ve iç tutarlılığı', 'Örneklem büyüklüğü', 'Etki büyüklüğünün işareti'], 'İki ifade aynı birlikteliği farklı nedensel yönlerde açıklar. Hangi yönün doğru olduğunu belirlemek zamansal sıra ve ek kanıt gerektirir.'),
  ('Bir şirket, çalışanlarına yeni ofis koltukları aldıktan sonra sırt ağrısı şikâyetlerinin azaldığını görüyor. Çalışanlar koltukların "sırt ağrısını önlemek için" alındığını biliyor. Bu bilgi sonucun yorumunu nasıl etkiler?', 'Beklenti etkisi azalmanın bir kısmını açıklayabilir.', ['Sonucun kesin olarak ve yalnızca koltuklardan kaynaklandığını kanıtlar.', 'Şikâyetlerin aslında arttığını gösterir.', 'Sırt ağrısının ölçülemeyeceğini kanıtlar.'], 'Çalışanlar iyileşme beklediği için şikâyetleri daha az bildirebilir. Öznel sonuçlarda plasebo benzeri etkiler göz önünde tutulmalıdır.'),
  ('Bir veri setinde kişilerin boy ve kilosunun yanı sıra ayakkabı numarası da var. Boy sabit tutulduğunda ayakkabı numarası ile kilo arasındaki ilişkinin büyük ölçüde kaybolması neyi gösterir?', 'İlişkinin büyük kısmının ortak bir değişken olan boydan kaynaklandığını', ['Ayakkabı numarasının kiloyu doğrudan ve kesin olarak belirlediğini', 'Boyun ölçülemediğini', 'Kilo ile boy arasında hiçbir ilişki olmadığını'], 'Bir değişken denetlendiğinde ilişki kayboluyorsa, o değişken iki değişkeni birlikte etkileyen ortak bir etkendir.'),
];
